import { Search } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { searchVehicleCatalog } from "../../api/agentClient";
import type { VehicleSearchItem } from "../../types/agent";

interface VehicleSearchBoxProps {
  value: string;
  onChange: (value: string) => void;
  onSelect: (item: VehicleSearchItem) => void;
}

const searchCache = new Map<string, VehicleSearchItem[]>();
const quickExamples = ["宝马3系", "奔驰C级", "凯美瑞", "比亚迪秦PLUS", "Model Y", "哈弗H6"];

function normalizeQuery(value: string) {
  return value.trim().replace(/\s+/g, "").toLowerCase();
}

export function VehicleSearchBox({ value, onChange, onSelect }: VehicleSearchBoxProps) {
  const [focused, setFocused] = useState(false);
  const [items, setItems] = useState<VehicleSearchItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const abortRef = useRef<AbortController | null>(null);
  const rootRef = useRef<HTMLDivElement>(null);
  const cacheKey = useMemo(() => normalizeQuery(value), [value]);

  useEffect(() => {
    if (!focused) return;
    function closeOutside(event: PointerEvent) {
      if (!rootRef.current?.contains(event.target as Node)) setFocused(false);
    }
    function closeOnEscape(event: KeyboardEvent) {
      if (event.key === "Escape") setFocused(false);
    }
    document.addEventListener("pointerdown", closeOutside);
    document.addEventListener("keydown", closeOnEscape);
    return () => {
      document.removeEventListener("pointerdown", closeOutside);
      document.removeEventListener("keydown", closeOnEscape);
    };
  }, [focused]);

  useEffect(() => {
    if (!focused || cacheKey.length < 2) {
      setItems([]);
      setLoading(false);
      setError("");
      abortRef.current?.abort();
      return;
    }

    const cached = searchCache.get(cacheKey);
    if (cached) {
      setItems(cached);
      setLoading(false);
      setError("");
      return;
    }

    const controller = new AbortController();
    abortRef.current?.abort();
    abortRef.current = controller;
    const timer = window.setTimeout(() => {
      setLoading(true);
      setError("");
      searchVehicleCatalog(value, 8, controller.signal)
        .then((results) => {
          searchCache.set(cacheKey, results.slice(0, 8));
          setItems(results.slice(0, 8));
        })
        .catch((err) => {
          if (controller.signal.aborted) return;
          setError(err instanceof Error ? err.message : "车型库查询失败");
          setItems([]);
        })
        .finally(() => {
          if (!controller.signal.aborted) setLoading(false);
        });
    }, 220);

    return () => {
      window.clearTimeout(timer);
      controller.abort();
    };
  }, [cacheKey, focused, value]);

  return (
    <div className="vehicle-search" ref={rootRef}>
      <div className="vehicle-search-input">
        <input
          value={value}
          onChange={(event) => onChange(event.target.value)}
          onFocus={() => setFocused(true)}
          placeholder="输入车型，如 2021款 宝马3系 320Li M运动套装"
        />
        <Search size={18} />
      </div>
      {focused && value.trim().length >= 2 && (
        <div className="vehicle-results">
          {loading && <p>正在查询车型库...</p>}
          {error && <p>{error}</p>}
          {!loading && !error && !items.length && <p>没有匹配项，可继续输入完整款型。</p>}
          {items.map((item) => (
            <button
              key={`${item.model_id || item.id || item.title}`}
              type="button"
              onClick={() => {
                onSelect(item);
                setFocused(false);
              }}
            >
              <strong>{item.title}</strong>
              <small>{[item.brand, item.series, item.model_year].filter(Boolean).join(" · ")}</small>
            </button>
          ))}
        </div>
      )}
      {focused && value.trim().length < 2 && (
        <div className="vehicle-results vehicle-results-compact">
          <p>输入品牌、车系、年款或款型关键词，例如“2021 宝马3系”。</p>
          <div className="vehicle-hotwords">
            {quickExamples.map((example) => (
              <button key={example} type="button" onMouseDown={(event) => event.preventDefault()} onClick={() => onChange(example)}>
                {example}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
