function PricingAgentConversation({ task, events }: { task: AgentTaskResponse; events: PricingAgentEvent[] }) {
  const visibleEvents = useRevealedPricingEvents(events, task);
  const plan = getLatestPlanEvent(visibleEvents);
  const groups = buildPricingTaskGroups(visibleEvents);
  const reportStarted = visibleEvents.some((event) => event.event_type === "final_report_started");
  const reportDone = visibleEvents.some((event) => event.event_type === "final_report_done");
  const finalReport = getFinalReportFromTask(task);
  const finalReportPlanned = events.some((event) =>
    event.event_type === "final_report_started" ||
    event.event_type === "final_report_delta" ||
    event.event_type === "final_report_done"
  );
  const reportBlocks = visibleEvents
    .filter((event) => event.event_type === "final_report_delta" && event.block)
    .map((event) => event.block!) as PricingAgentReportBlock[];
  const intro = visibleEvents.find((event) => event.event_type === "agent_intro")?.text || task.agent_intro;
  const taskStreamDone = groups.length > 0 && groups.every((group) => group.done);
  if (reportDone) {
    return (
      <div className="task-conversation pricing-agent-conversation">
        <p className="agent-intro">{intro}</p>
        <PricingAgentProcessDisclosure plan={plan} task={task} groups={groups} />
        <AutoPositionedResult taskId={task.task_id}>
          <PricingAgentInlineReport
            blocks={reportBlocks.length ? reportBlocks : finalReport?.blocks || []}
            report={finalReport}
            task={task}
            done
          />
        </AutoPositionedResult>
      </div>
    );
  }
  return (
    <div className="task-conversation pricing-agent-conversation">
      <p className="agent-intro">{intro}</p>
      {plan ? <PricingAgentPlanCard plan={plan} task={task} /> : <TaskPlanCard task={task} defaultOpen />}
      <PricingAgentExecutionStream groups={groups} />
      {reportStarted ? (
        <PricingAgentInlineReport
          blocks={reportBlocks}
          report={finalReport}
          task={task}
          done={reportDone}
        />
      ) : taskStreamDone && task.final_result && !finalReportPlanned ? (
        <AutoPositionedResult taskId={task.task_id}>
          <FinalResultPanel result={task.final_result} taskPlan={task.task_plan} />
        </AutoPositionedResult>
      ) : null}
    </div>
  );
}

function useRevealedPricingEvents(events: PricingAgentEvent[], task: AgentTaskResponse) {
  const revealAll = shouldRevealAllPricingEvents(events, task);
  const initialCount = getInitialPricingEventCount(events, task, revealAll);
  const [count, setCount] = useState(initialCount);
  const eventKey = events.map((event) => `${event.event_type}:${event.task_id || ""}:${event.title || ""}`).join("|");
  useEffect(() => {
    const nextInitial = getInitialPricingEventCount(events, task, revealAll);
    setCount((value) => Math.min(events.length, Math.max(value, nextInitial)));
  }, [eventKey, events.length, revealAll, task]);
  useEffect(() => {
    if (revealAll) return;
    if (!events.length || count >= events.length) return;
    const delayMs = getPricingEventDelay(task, events[count]);
    const timer = window.setTimeout(() => {
      setCount((value) => Math.min(events.length, value + 1));
    }, delayMs);
    return () => window.clearTimeout(timer);
  }, [count, events, events.length, eventKey, revealAll, task]);
  return events.slice(0, revealAll ? events.length : count);
}

function getInitialPricingEventCount(events: PricingAgentEvent[], task: AgentTaskResponse, revealAll: boolean) {
  if (revealAll) return events.length;
  if (!events.length) return 0;
  const pendingOnly = Boolean(task.raw_response?.pricing_agent?.llm_audit?.pending_only);
  const firstToolRunningIndex = events.findIndex((event) => event.event_type === "tool_running" || event.event_type === "tool_searching");
  if (firstToolRunningIndex >= 0) return firstToolRunningIndex + 1;
  const firstStepIndex = events.findIndex((event) => event.event_type === "step_started" || event.event_type === "task_started");
  if (firstStepIndex >= 0) return firstStepIndex + 1;
  if (!pendingOnly) {
    const planDoneIndex = events.findIndex((event) => event.event_type === "plan_done");
    if (planDoneIndex >= 0) return planDoneIndex + 1;
  }
  return Math.min(events.length, 3);
}

function shouldRevealAllPricingEvents(events: PricingAgentEvent[], task: AgentTaskResponse) {
  void events;
  const mode = String(task.raw_response?.pricing_agent?.streaming?.mode || "");
  return mode === "reveal_all";
}

function getPricingEventDelay(task: AgentTaskResponse, event?: PricingAgentEvent) {
  const raw = task.raw_response?.pricing_agent?.streaming?.delay_ms;
  const number = Number(raw);
  if (import.meta.env.MODE === "test" && Number.isFinite(number) && number > 0) {
    return Math.min(number, 20);
  }
  const base = Number.isFinite(number) && number > 0 ? Math.max(140, number) : 180;
  switch (event?.event_type) {
    case "plan_started":
      return 80;
    case "plan_done":
      return 120;
    case "task_started":
      return base;
    case "tool_searching":
      return 100;
    case "stage_explaining":
      return 140;
    case "task_result_table_delta":
      return 60;
    case "task_done":
      return base;
    case "final_report_started":
      return 140;
    case "final_report_delta":
      return 80;
    case "final_report_done":
      return 160;
    default:
      return base;
  }
}

function getPricingAgentEvents(task: AgentTaskResponse): PricingAgentEvent[] {
  const raw = task.raw_response as InteractionTurnResponse | undefined;
  const fromTop = Array.isArray(raw?.pricing_agent_events) ? raw?.pricing_agent_events : [];
  const fromAgent = Array.isArray(raw?.pricing_agent?.events) ? raw?.pricing_agent?.events : [];
  return (fromTop.length ? fromTop : fromAgent) as PricingAgentEvent[];
}

function getLatestPlanEvent(events: PricingAgentEvent[]) {
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index];
    if (event.event_type === "plan_done" && event.task_plan) return event.task_plan;
  }
  return undefined;
}

interface PricingTaskGroup {
  task_id?: string;
  title: string;
  message?: string;
  currentDoing?: string;
  toolProgress?: string[];
  sourceMessages: string[];
  columns: string[];
  rows: Array<Array<string | number | null>>;
  summary?: string;
  metricChips?: string[];
  details?: string;
  sources?: string[];
  trustSources?: string[];
  whyTrust?: string;
  businessMeaning?: string;
  priceImpact?: string;
  action?: string;
  needReview?: string;
  llmExplained?: boolean;
  dailyNote?: string;
  businessExplanation?: NonNullable<PricingAgentEvent["business_explanation"]>;
  done?: boolean;
}

function buildPricingTaskGroups(events: PricingAgentEvent[]): PricingTaskGroup[] {
  const groups: PricingTaskGroup[] = [];
  const byId = new Map<string, PricingTaskGroup>();
  function ensure(taskId: string | undefined, title?: string) {
    const key = taskId || `task-${groups.length + 1}`;
    let group = byId.get(key);
    if (!group) {
      group = { task_id: taskId, title: title || "任务执行", sourceMessages: [], columns: [], rows: [] };
      byId.set(key, group);
      groups.push(group);
    }
    if (title) group.title = title;
    return group;
  }
  events.forEach((event) => {
    if (event.event_type === "step_started" || event.event_type === "task_started") {
      const group = ensure(event.task_id, event.step_name || event.title);
      const text = event.display_text || event.message;
      group.message = text;
      group.currentDoing = text || group.currentDoing;
      if (event.business_explanation) group.businessExplanation = event.business_explanation;
    }
    if (event.event_type === "tool_running" || event.event_type === "tool_searching") {
      const group = ensure(event.task_id, event.step_name || event.title);
      const text = event.display_text || event.message;
      if (text) {
        group.toolProgress = [...(group.toolProgress || []), text];
        if (!group.sourceMessages.includes(text)) group.sourceMessages.push(text);
      }
    }
    if (event.event_type === "tool_done") {
      const group = ensure(event.task_id, event.step_name || event.title);
      const text = event.display_text || event.message;
      if (text) {
        group.toolProgress = [...(group.toolProgress || []), text];
        if (!group.sourceMessages.includes(text)) group.sourceMessages.push(text);
      }
    }
    if (event.event_type === "llm_explaining" || event.event_type === "stage_explaining") {
      const group = ensure(event.task_id, event.step_name || event.title);
      const text = event.display_text || event.message;
      if (text && !group.sourceMessages.includes(text)) group.sourceMessages.push(text);
      group.llmExplained = event.llm_explained;
    }
    if (event.event_type === "task_result_table_delta") {
      const group = ensure(event.task_id, event.title);
      if (event.columns?.length) group.columns = event.columns;
      if (event.row?.length) group.rows.push(event.row);
    }
    if (event.event_type === "step_done" || event.event_type === "task_done") {
      const group = ensure(event.task_id, event.step_name || event.title);
      group.done = true;
      group.summary = event.stage_conclusion || event.summary;
      group.businessMeaning = event.business_meaning || group.businessMeaning;
      group.priceImpact = event.business_impact || group.priceImpact;
      group.action = event.next_action || group.action;
      if (event.business_explanation) group.businessExplanation = event.business_explanation;
      if (event.table) {
        group.columns = event.table.columns || group.columns;
        group.rows = event.table.rows || group.rows;
        group.metricChips = event.table.metric_chips || [];
        group.details = event.table.details;
        group.sources = event.table.sources || [];
        group.trustSources = event.table.trust_sources || event.table.sources || [];
        group.whyTrust = event.table.why_trust;
        group.businessMeaning = event.table.business_meaning;
        group.priceImpact = event.table.price_impact;
        group.action = event.table.action;
        group.needReview = event.table.need_review;
        group.llmExplained = Boolean(event.table.llm_explained);
        group.dailyNote = event.table.daily_note;
        if (event.table.business_explanation) group.businessExplanation = event.table.business_explanation;
      }
    }
  });
  return groups;
}

