function PricingAgentStepBrief({ group }: { group: PricingTaskGroup }) {
  const explanation = group.businessExplanation;
  const lines = group.done ? [
    { label: "阶段结论", text: explanation?.one_line_conclusion || group.summary },
    { label: "对报价的影响", text: explanation?.business_impact || group.priceImpact || group.businessMeaning },
    { label: "下一步", text: explanation?.next_action || group.action }
  ] : [
    { label: "正在做什么", text: explanation?.business_impact || group.currentDoing || group.message },
    { label: "下一步", text: explanation?.next_action || group.action || "等这一步完成后继续判断报价边界" }
  ].filter((item) => item.text);
  const keyMetrics = Array.isArray(explanation?.key_metrics) ? explanation?.key_metrics.slice(0, 4) : [];
  if (!lines.length) return null;
  return (
    <div className="pricing-agent-step-brief">
      {keyMetrics.length ? (
        <div className="pricing-agent-metric-chips step-metrics">
          {keyMetrics.map((item, index) => (
            <span key={`${safeText(item.label)}-${index}`}>{safeText(item.label)} {safeText(item.value)}</span>
          ))}
        </div>
      ) : null}
      {lines.map((item) => (
        <p key={item.label}>
          <strong>{item.label}：</strong>
          <span>{safeText(stripBriefPrefix(item.text, item.label))}</span>
        </p>
      ))}
    </div>
  );
}

function stripBriefPrefix(text: unknown, label: string) {
  const value = safeText(text);
  const pattern = new RegExp(`^${label}\\s*[:：]\\s*`);
  return value.replace(pattern, "");
}

