function getPricingTaskVehicleSlots(task: AgentTaskResponse) {
  const resultMetrics = task.final_result?.metrics || {};
  const responseSlots = task.raw_response?.slots as Record<string, unknown> | undefined;
  const planSlots = task.task_plan.six_elements || {};
  const metricSlots =
    (resultMetrics.six_elements as Record<string, unknown> | undefined) ||
    (resultMetrics.slots as Record<string, unknown> | undefined) ||
    {};
  return {
    ...(responseSlots || {}),
    ...(planSlots || {}),
    ...metricSlots,
  };
}

function getFinalReportFromTask(task: AgentTaskResponse): PricingAgentFinalReport | undefined {
  const fromAgent = task.raw_response?.pricing_agent?.final_report;
  const fromMetrics = task.final_result?.metrics?.pricing_final_report as PricingAgentFinalReport | undefined;
  return fromAgent || fromMetrics;
}

const PRICING_FEEDBACK_TAGS = [
  "有用",
  "没用",
  "价格偏高",
  "价格偏低",
  "车型识别错",
  "售车价不准",
  "利润测算不准"
];

function PricingFeedbackPanel({
  task,
  report,
  result,
  calculator
}: {
  task?: AgentTaskResponse;
  report?: PricingAgentFinalReport;
  result?: AgentFinalResult;
  calculator?: PricingCalculatorState;
}) {
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [comment, setComment] = useState("");
  const [adoptedPurchasePrice, setAdoptedPurchasePrice] = useState("");
  const [adoptedSalePrice, setAdoptedSalePrice] = useState("");
  const [customerAccepted, setCustomerAccepted] = useState("");
  const [rejectReason, setRejectReason] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [status, setStatus] = useState<string>("");
  const showDetails = selectedTags.some((tag) => tag !== "有用");

  function toggleTag(tag: string) {
    setStatus("");
    setSelectedTags((items) => items.includes(tag) ? items.filter((item) => item !== tag) : [...items, tag]);
  }

  async function submitFeedback() {
    if (!selectedTags.length || submitting) return;
    setSubmitting(true);
    setStatus("");
    const payload = buildPricingFeedbackPayload({
      task,
      report,
      result,
      tags: selectedTags,
      comment,
      adoptedPurchasePrice,
      adoptedSalePrice,
      customerAccepted,
      rejectReason,
      calculator
    });
    try {
      const response = await submitPricingFeedback(payload);
      const preview = response.reflection_preview || response.data?.reflection_preview;
      setStatus(preview ? `已记录：${preview}` : "已记录，本次反馈会用于优化下次相似任务的话术和解释，不会直接改写模型价格。");
      setSelectedTags([]);
      setComment("");
      setAdoptedPurchasePrice("");
      setAdoptedSalePrice("");
      setCustomerAccepted("");
      setRejectReason("");
    } catch (error) {
      setStatus(error instanceof Error ? error.message : "反馈提交失败，请稍后再试。");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <section className="pricing-feedback-panel">
      <div className="pricing-feedback-head">
        <div>
          <strong>这个结果对业务有帮助吗？</strong>
          <span>你的反馈会用于优化下次相似任务的话术和解释。</span>
        </div>
      </div>
      <div className="pricing-feedback-tags">
        {PRICING_FEEDBACK_TAGS.map((tag) => (
          <button
            key={tag}
            type="button"
            className={selectedTags.includes(tag) ? "selected" : ""}
            onClick={() => toggleTag(tag)}
          >
            {tag}
          </button>
        ))}
      </div>
      {showDetails ? (
        <>
          <div className="pricing-feedback-fields">
            <label>
              <span>实际采纳收车价（万，可选）</span>
              <input value={adoptedPurchasePrice} onChange={(event) => setAdoptedPurchasePrice(event.target.value)} placeholder="例如 13.8" />
            </label>
            <label>
              <span>实际采纳售车价（万，可选）</span>
              <input value={adoptedSalePrice} onChange={(event) => setAdoptedSalePrice(event.target.value)} placeholder="例如 15.2" />
            </label>
            <label>
              <span>客户是否接受</span>
              <select value={customerAccepted} onChange={(event) => setCustomerAccepted(event.target.value)}>
                <option value="">未确定</option>
                <option value="accepted">已接受</option>
                <option value="rejected">已拒绝</option>
              </select>
            </label>
            <label>
              <span>客户拒绝原因（可选）</span>
              <input value={rejectReason} onChange={(event) => setRejectReason(event.target.value)} placeholder="例如 觉得网上挂价更高" />
            </label>
          </div>
          <label className="pricing-feedback-comment">
            <span>补充说明（可选）</span>
            <textarea value={comment} onChange={(event) => setComment(event.target.value)} placeholder="哪里不好用、客户怎么反馈、你希望下次怎么说" />
          </label>
        </>
      ) : null}
      <div className="pricing-feedback-submit">
        <button type="button" disabled={!selectedTags.length || submitting} onClick={submitFeedback}>
          {submitting ? "提交中..." : "提交反馈"}
        </button>
        {status ? <small>{status}</small> : null}
      </div>
    </section>
  );
}

function buildPricingFeedbackPayload({
  task,
  report,
  result,
  tags,
  comment,
  adoptedPurchasePrice,
  adoptedSalePrice,
  customerAccepted,
  rejectReason,
  calculator
}: {
  task?: AgentTaskResponse;
  report?: PricingAgentFinalReport;
  result?: AgentFinalResult;
  tags: string[];
  comment: string;
  adoptedPurchasePrice: string;
  adoptedSalePrice: string;
  customerAccepted: string;
  rejectReason: string;
  calculator?: PricingCalculatorState;
}): PricingFeedbackPayload {
  const slots = task ? getPricingTaskVehicleSlots(task) : ((result?.metrics?.six_elements || result?.metrics?.slots || {}) as Record<string, unknown>);
  const raw = task?.raw_response;
  const priceResult = raw?.pricing?.price_result as Record<string, unknown> | undefined;
  const traceId = safeText(
    raw?.pricing_workflow?.trace_id ||
    raw?.pricing_report_context?.trace_id ||
    raw?.pricing_report_context?.quote_id ||
    priceResult?.quote_id ||
    priceResult?.trace_id ||
    ""
  );
  const outcome = customerAccepted === "accepted" || tags.includes("客户已接受")
    ? "accepted"
    : customerAccepted === "rejected" || tags.includes("客户已拒绝")
      ? "rejected"
      : "";
  const systemPurchase = calculator?.systemPurchaseYuan || report?.point_price_yuan || report?.purchase_price_yuan || numberFromUnknown(result?.metrics?.point_price);
  const currentPurchase = calculator?.currentPurchaseYuan || systemPurchase;
  const systemSale = calculator?.systemSaleYuan || report?.sale_price_yuan || numberFromUnknown(result?.metrics?.b2c_point);
  const currentSale = calculator?.currentSaleYuan || systemSale;
  const gross = calculator?.grossYuan || report?.gross_profit_yuan || report?.gross_profit || result?.metrics?.gross_profit;
  return {
    module: "pricing",
    task_type: task?.task_type || "purchase_price",
    trace_id: traceId,
    task_id: task?.task_id || "",
    report_id: safeText((report?.price_reasoning as Record<string, unknown> | undefined)?.quote_id || priceResult?.quote_id || traceId),
    user_query: safeText(raw?.text || raw?.reply?.text || ""),
    vehicle_slots: slots,
    vehicle_fingerprint: buildVehicleFingerprint(slots),
    purchase_price: systemPurchase,
    purchase_price_upper: calculator?.upperYuan || report?.upper_yuan || numberFromUnknown(result?.metrics?.upper),
    sale_price: systemSale,
    system_purchase_price: systemPurchase,
    user_adjusted_purchase_price: currentPurchase,
    system_sale_price: systemSale,
    user_adjusted_sale_price: currentSale,
    actual_purchase_price: parseWanInput(adoptedPurchasePrice),
    actual_sale_price: parseWanInput(adoptedSalePrice),
    gross_profit: numberFromUnknown(gross),
    estimated_profit: numberFromUnknown(gross),
    calculator_snapshot: calculator ? {
      system_purchase_price: calculator.systemPurchaseYuan,
      current_purchase_price: calculator.currentPurchaseYuan,
      system_sale_price: calculator.systemSaleYuan,
      current_sale_price: calculator.currentSaleYuan,
      recon_cost: calculator.reconYuan,
      platform_cost: calculator.platformYuan,
      risk_buffer: calculator.bufferYuan,
      gross_profit: calculator.grossYuan,
      gross_profit_rate: calculator.grossRate,
    } : undefined,
    tags,
    comment,
    free_text: comment,
    adopted_purchase_price: parseWanInput(adoptedPurchasePrice),
    adopted_sale_price: parseWanInput(adoptedSalePrice),
    accepted_by_customer: customerAccepted ? customerAccepted === "accepted" : undefined,
    business_outcome: outcome || undefined,
    customer_reject_reason: rejectReason,
    feedbackKind: "explicit"
  };
}

function buildVehicleFingerprint(slots: Record<string, unknown>) {
  return [
    slots.standard_vehicle || slots.series || slots.model,
    slots.first_license_date || slots.first_license_year,
    slots.mileage_wan_km,
    slots.city,
    slots.transfer_count,
    slots.color
  ].filter((item) => item !== undefined && item !== null && item !== "").map(String).join("|");
}

function parseWanInput(value: string): number | undefined {
  const number = parseNumberInput(value);
  if (number === undefined) return undefined;
  return number < 1000 ? Math.round(number * 10000) : number;
}

function parseNumberInput(value: string): number | undefined {
  const text = value.trim().replace(/,/g, "");
  if (!text) return undefined;
  const number = Number(text);
  return Number.isFinite(number) ? number : undefined;
}

function numberFromUnknown(value: unknown): number | undefined {
  const number = typeof value === "number" ? value : Number(value);
  return Number.isFinite(number) ? number : undefined;
}

