function IntentRouteTrace({ route }: { route: Record<string, unknown> }) {
  const confidence = Number(route.confidence);
  const blockedBy = Array.isArray(route.blocked_by) ? route.blocked_by.map((field) => slotLabel(String(field))).join("、") : "";
  const businessGoal = safeText(route.business_goal, moduleIntentLabel(route.module_intent || route.module));
  const businessTask = safeText(route.business_task, taskIntentLabel(route.task_intent || route.internal_intent || route.legacy_intent));
  const businessScope = safeText(route.business_scope, priceRoleMeaning(route.price_role));
  const executionReason = safeText(route.execution_reason, routeDecisionLabel(String(route.decision || "")));
  return (
    <section className="intent-route-trace" aria-label="本轮任务理解">
      <div>
        <span>你想完成的事</span>
        <strong>{businessGoal}</strong>
        <small>先确认本轮属于哪项业务，避免串到别的模块。</small>
      </div>
      <div>
        <span>本次具体任务</span>
        <strong>{businessTask}</strong>
        <small>说明这一次具体要查什么、算什么或推荐什么。</small>
      </div>
      <div>
        <span>本环节负责什么</span>
        <strong>{businessScope}</strong>
        <small>明确这个环节会给出什么，也明确不会越界做什么。</small>
      </div>
      <div>
        <span>为什么这样执行</span>
        <strong>{executionReason}</strong>
        <small>告诉一线系统为何选择这条业务链路。</small>
      </div>
      <p className="intent-confidence-line">
        任务识别把握：<strong>{Number.isFinite(confidence) ? `${Math.round(confidence * 100)}%` : "待确认"}</strong>
        <span>（表示系统对“用户要做什么”的判断把握，不代表最终选品或定价准确率。）</span>
      </p>
      {blockedBy ? <p className="intent-blocked-fields">缺失字段：{blockedBy}</p> : null}
      {route.internal_intent || route.legacy_intent || route.workflow_name ? (
        <details className="tech-details">
          <summary>查看系统审计说明</summary>
          <p>系统已完成任务识别、模块防串线和执行条件校验；内部编号默认不向一线展示。</p>
        </details>
      ) : null}
    </section>
  );
}

