function SixElementGrid({ values }: { values: Record<string, unknown> }) {
  const inspectionVerified = Boolean(
    values.inspection_verified
    || values.has_real_inspection
    || ["verified", "completed", "已检测", "已验车"].includes(String(values.inspection_status || "").toLowerCase())
  );
  const conditionIsDefault = Boolean(values.condition_is_default) || String(values.condition || "").includes("系统默认良好");
  const conditionValue = conditionIsDefault
    ? "良好（默认估算，未实车检测）"
    : formatCondition(values.condition_group || values.inspection_grade || values.condition);
  const rows: Array<{ label: string; value: unknown; partial?: boolean; note?: string }> = [
    {
      label: values.standard_vehicle ? "标准车型" : "车型线索",
      value: values.standard_vehicle || formatVehicleClue(values),
      partial: !values.standard_vehicle && Boolean(values.series)
    },
    { label: "上牌时间", value: formatFirstLicense(values) },
    { label: "里程", value: values.mileage_wan_km !== undefined && values.mileage_wan_km !== null ? `${safeText(values.mileage_wan_km)} 万公里` : undefined },
    { label: "城市", value: values.city },
    { label: "过户", value: values.transfer_count !== undefined && values.transfer_count !== null ? `${safeText(values.transfer_count)} 次` : undefined },
    { label: "颜色", value: values.color },
    {
      label: "车况",
      value: conditionValue,
      partial: Boolean(conditionValue) && !inspectionVerified,
      note: conditionValue && !inspectionVerified ? "待实车检测确认" : undefined
    }
  ];
  return (
    <div className="six-element-grid slot-badge-grid" aria-label="车辆七要素">
      {rows.map(({ label, value, partial, note }) => {
        const missing = value === undefined || value === null || value === "";
        const status = missing ? "missing" : partial ? "partial" : "verified";
        return <div key={label} className={`slot-badge ${status}`}>
          <span className="slot-icon" aria-hidden="true">
            {missing ? <AlertTriangle size={16} /> : partial ? <Info size={16} /> : <CheckCircle2 size={16} />}
          </span>
          <div>
            <span className="slot-label">{label}</span>
            <strong className="slot-value">{safeText(value, "缺失")}</strong>
            {partial ? <small>{note || "待确认具体款型"}</small> : null}
          </div>
        </div>
      })}
    </div>
  );
}

function formatVehicleClue(values: Record<string, unknown>) {
  const brand = safeText(values.brand, "");
  let series = safeText(values.series, "");
  if (brand && series.replace(/\s+/g, "").startsWith(brand.replace(/\s+/g, ""))) {
    series = series.slice(series.indexOf(brand) + brand.length).trim();
  }
  return [values.model_year ? `${values.model_year}款` : "", brand, series].filter(Boolean).join(" ");
}

function formatCondition(value: unknown) {
  const text = String(value || "").trim();
  if (!text) return undefined;
  if (/^[ABCD]$/i.test(text)) return `${text.toUpperCase()}级车况`;
  return ({ excellent: "A级车况", good: "B级车况", fair: "C级车况", poor: "D级车况" } as Record<string, string>)[text.toLowerCase()] || text;
}

function formatFirstLicense(values: Record<string, unknown>) {
  const raw = String(values.first_license_date || values.reg_date || "").trim().replace("/", "-");
  const rawMatch = raw.match(/^((?:19|20)\d{2})(?:-(\d{1,2}))?/);
  if (rawMatch) {
    const month = rawMatch[2] || values.first_license_month;
    return month ? `${rawMatch[1]}-${String(month).padStart(2, "0")}` : rawMatch[1];
  }
  if (values.first_license_year) {
    const month = values.first_license_month ? `-${String(values.first_license_month).padStart(2, "0")}` : "";
    return `${values.first_license_year}${month}`;
  }
  return undefined;
}

