function MetricHelp({ label, children }: { label: string; children: string }) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (!open) return;
    function closeOutside(event: PointerEvent) {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false);
    }
    document.addEventListener("pointerdown", closeOutside);
    return () => document.removeEventListener("pointerdown", closeOutside);
  }, [open]);
  return (
    <span
      className="metric-help-control"
      ref={rootRef}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
      onFocus={() => setOpen(true)}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setOpen(false);
      }}
    >
      <button
        type="button"
        aria-label={`解释${label}`}
        aria-expanded={open}
        onClick={(event) => {
          event.stopPropagation();
          setOpen((value) => !value);
        }}
      >
        <Info size={13} />
      </button>
      {open ? <span className="metric-help-popover" role="tooltip"><strong>{label}</strong>{children}</span> : null}
    </span>
  );
}

function VehiclePhoto({ item, variant = "card" }: { item: Record<string, unknown>; variant?: "card" | "hero" | "pricing" }) {
  const embedded = (item.official_photo || {}) as Record<string, unknown>;
  const directPhoto = safeText(embedded.proxied_image_url || embedded.image_url, "");
  const [src, setSrc] = useState(directPhoto || fallbackVehicleImage);
  const [usingFallback, setUsingFallback] = useState(!directPhoto);
  const brand = safeText(item.brand || item.brand_name, "");
  const series = safeText(item.series || item.series_name || item.standard_vehicle || item.model, "");

  useEffect(() => {
    const direct = safeText(embedded.proxied_image_url || embedded.image_url, "");
    if (direct) {
      setSrc(direct);
      setUsingFallback(false);
      return;
    }
    if (!series) {
      setSrc(fallbackVehicleImage);
      setUsingFallback(true);
      return;
    }
    const params = new URLSearchParams({ brand, series });
    let active = true;
    fetch(`/api/vehicle/photo?${params.toString()}`)
      .then((response) => response.ok ? response.json() : Promise.reject(new Error("photo unavailable")))
      .then((payload) => {
        const photo = (payload.data || {}) as Record<string, unknown>;
        if (active) {
          const resolved = safeText(photo.proxied_image_url || photo.image_url, "");
          setSrc(resolved || fallbackVehicleImage);
          setUsingFallback(!resolved);
        }
      })
      .catch(() => {
        if (active) {
          setSrc(fallbackVehicleImage);
          setUsingFallback(true);
        }
      });
    return () => { active = false; };
  }, [brand, embedded.image_url, embedded.proxied_image_url, series]);

  return (
    <figure className={`vehicle-photo vehicle-photo-${variant} ${usingFallback ? "vehicle-photo-placeholder" : ""}`}>
      <img
        src={src || fallbackVehicleImage}
        alt={`${brand}${series} 车型图片`}
        loading={variant === "card" ? "eager" : "eager"}
        decoding="async"
        onError={() => {
          setSrc(fallbackVehicleImage);
          setUsingFallback(true);
        }}
      />
      {variant !== "card" ? <figcaption>{usingFallback ? "车型示意图" : "懂车帝官方车型图"}</figcaption> : null}
    </figure>
  );
}

function selectionItemTitle(item: Record<string, unknown>): string {
  const brand = safeText(item.brand, "");
  const series = safeText(item.series || item.title, "");
  const vehicle = brand && series && !series.includes(brand) ? `${brand} ${series}` : series || brand;
  const year = safeText(item.model_year, "");
  const model = safeText(item.model, "");
  if (year && year !== "多年份聚合") {
    return `${vehicle}${vehicle ? " · " : ""}${year}款${model ? ` ${model}` : ""}`;
  }
  return vehicle;
}

