function isSelectionExportAction(action: string) {
  return /(导出|下载)/.test(action) && /(选品|策略|报告|清单|明细|Excel)/i.test(action);
}

function SelectionFullReportDialog({
  result,
  onClose
}: {
  result: AgentFinalResult;
  onClose: () => void;
}) {
  const metrics = result.metrics || {};
  const scope = (metrics.scope || {}) as Record<string, unknown>;
  const riskItems = Array.isArray(metrics.risk_items) ? metrics.risk_items as Record<string, unknown>[] : [];
  const strictAvoidItems = Array.isArray(metrics.strict_avoid_items) ? metrics.strict_avoid_items as Record<string, unknown>[] : [];
  const isRiskList = result.title.includes("避免收");
  const resultRows = result.items || [];
  const rows = isRiskList ? [] : resultRows;
  const allCandidates = Array.isArray(metrics.all_candidates) ? metrics.all_candidates as Record<string, unknown>[] : resultRows;
  const avoidRows = isRiskList ? mergeSelectionAvoidRows(allCandidates, resultRows) : mergeSelectionAvoidRows(allCandidates, [...strictAvoidItems, ...riskItems]);
  const analyzedCount = allCandidates.length;
  return (
    <div className="pricing-report-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}>
      <section tabIndex={-1} className="pricing-report-dialog selection-full-report-dialog" role="dialog" aria-modal="true" aria-label="选品决策报告">
        <header className="report-dialog-header">
          <div><span>AI懂车价</span><strong>选品决策报告</strong></div>
          <div>
            <button type="button" onClick={onClose} aria-label="关闭选品报告" title="关闭"><X size={20} /></button>
          </div>
        </header>
        <div className="pricing-report-content selection-full-report-content">
          <section className="report-vehicle-header">
            <div><p>任务范围</p><h2>{safeText(scope.city, "全国")}选品</h2></div>
            <div className="selection-report-scope">
              {(result.filters || []).map((filter) => <span key={filter}>{filter}</span>)}
            </div>
          </section>
          <section className="report-section business-report-section">
            <h3>结论</h3><p>{result.summary}</p>
            <div className="selection-report-kpis">
              <div><span>本轮分析车系</span><strong>{analyzedCount}</strong></div>
              <div><span>推荐收的车</span><strong>{rows.length}</strong></div>
              <div><span>避免收的车</span><strong>{avoidRows.length}</strong></div>
              <div><span>数据窗口</span><strong>{safeText(scope.time_window, "90天")}</strong></div>
            </div>
          </section>
          {rows.length ? <SelectionEvidenceTable title="推荐收的车" rows={rows} /> : (
            <section className="report-section business-report-section"><h3>推荐收的车</h3><p>当前筛选条件下没有达到主动收车资格的车型；系统没有用观察项补位，也没有回退到其他筛选条件。</p></section>
          )}
          {avoidRows.length ? <SelectionEvidenceTable title="避免收的车" rows={avoidRows} /> : (
            <section className="report-section business-report-section"><h3>避免收的车</h3><p>当前筛选条件下没有达到明确规避阈值的车型；普通观察项不会被强行归为避免收。</p></section>
          )}
          <section className="report-section business-report-section">
            <h3>为什么可以信任</h3>
            <p>DSI 与行情状态先确定是否具备推荐资格；平均周转、单车典型毛利、总毛利贡献、亏损车占比和证据完整度再决定同一资格池内的先后顺序。日报与政策只解释风险，不重复计分。</p>
          </section>
        </div>
      </section>
    </div>
  );
}

function mergeSelectionAvoidRows(allCandidates: Record<string, unknown>[], riskItems: Record<string, unknown>[]) {
  const seen = new Set<string>();
  return [...riskItems, ...allCandidates.filter((item) => Boolean(item.business_avoid))].filter((item) => {
    const level = safeText(item.recommendation_level || item.selection_level, "").toUpperCase();
    if (!item.business_avoid && !["AVOID", "CAUTION"].includes(level)) return false;
    const key = [safeText(item.brand), safeText(item.series)].join("|");
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).map((item) => ({
    ...item,
    recommendation_label: "避免收",
    action: safeText(item.action, "不主动补库；已有库存优先去化")
  }));
}

function SelectionEvidenceTable({ title, rows }: { title: string; rows: Record<string, unknown>[] }) {
  return (
    <section className="report-section business-report-section selection-evidence-section">
      <h3>{title}</h3>
      <div className="selection-evidence-table-wrap">
        <table className="selection-evidence-table">
          <thead><tr><th>车系</th><th>供需状态</th><th>平均周转</th><th>单车典型毛利</th><th>亏损车占比</th><th>90天总毛利贡献</th><th>成交价带</th><th>建议动作</th></tr></thead>
          <tbody>
            {rows.slice(0, 100).map((item, index) => {
              const dsi = item.dsi_signal && typeof item.dsi_signal === "object" ? item.dsi_signal as Record<string, unknown> : {};
              return (
                <tr key={`${safeText(item.series)}-${index}`}>
                  <td><strong>{safeText(item.series)}</strong><small>{safeText(item.sample_note)}</small></td>
                  <td>{safeText(dsi.label, "未知")}</td>
                  <td>{safeText(item.avg_deal_cycle, "-")}天</td>
                  <td>{formatSignedWan(item.median_gross_profit)}</td>
                  <td>{formatOptionalPercent(item.loss_rate)}</td>
                  <td>{formatSelectionProfitContribution(item)}</td>
                  <td>{formatSelectionPriceBand(item)}</td>
                  <td>{safeText(item.action || item.recommendation_label, "结合库存复核")}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </section>
  );
}

function selectionDsiLabel(item: Record<string, unknown>) {
  const dsi = item.dsi_signal && typeof item.dsi_signal === "object"
    ? item.dsi_signal as Record<string, unknown>
    : {};
  return safeText(dsi.label || item.dsi_label, "未知");
}

function formatSelectionProfitContribution(item: Record<string, unknown>) {
  const signedProfit = numberFromUnknown(item.national_series_total_profit_90d);
  const observed = numberFromUnknown(item.profit_observed_count);
  const median = numberFromUnknown(item.median_gross_profit);
  const lossRate = numberFromUnknown(item.loss_rate);
  const contribution = numberFromUnknown(item.total_profit_contribution);
  if (observed !== undefined && observed <= 0) return "暂无可核验毛利";
  if (signedProfit !== undefined && signedProfit <= 0 && (median || 0) > 0 && (lossRate || 0) <= 0) return "累计口径待补齐";
  if (signedProfit !== undefined && signedProfit <= 0) return "累计毛利为负";
  if (contribution === undefined) return "暂无贡献口径";
  return formatPercentFromRatio(contribution);
}

function formatSelectionPriceBand(item: Record<string, unknown>) {
  const low = numberFromUnknown(item.deal_price_low_90d);
  const high = numberFromUnknown(item.deal_price_high_90d);
  if (low !== undefined && high !== undefined) return `${formatReportWan(low)}-${formatReportWan(high)}`;
  if (high !== undefined) return `${formatReportWan(high)}以内`;
  if (low !== undefined) return `${formatReportWan(low)}以上`;
  return "暂无";
}

function formatPriceScopeYears(item: Record<string, unknown>) {
  const years = Array.isArray(item.price_scope_model_years)
    ? item.price_scope_model_years.map((value) => safeText(value)).filter(Boolean)
    : [];
  if (!years.length) return "";
  return years.slice(0, 4).join("/") + (years.length > 4 ? "等" : "");
}

function buildLocalSelectionActionTask(
  title: string,
  summary: string,
  items: Record<string, unknown>[],
  actions: string[],
  module: BusinessModule = "selection"
): AgentTaskResponse {
  return {
    module,
    task_id: `local_${Date.now().toString(36)}`,
    task_type: "selection_local_action",
    agent_intro: summary,
    task_plan: {
      title,
      status: "done",
      understanding: summary,
      steps: ["读取当前选品结果", "执行本地确认动作", "生成下一步业务入口"]
    },
    task_execution: [
      { name: "selection_ui_action", status: "done", detail: title },
      { name: "response_composer", status: "done", detail: "已生成前端确认结果" }
    ],
    final_result: {
      type: "selection_result",
      title,
      summary,
      items,
      actions
    },
    follow_up_questions: [],
    stream_status: "done",
    stream_stage: "done"
  };
}

