function DiscountRankingControls({
  metrics,
  onUpdate
}: {
  metrics: Record<string, unknown>;
  onUpdate: (next: {
    title: string;
    summary: string;
    metrics: Record<string, unknown>;
    items: Record<string, unknown>[];
  }) => void;
}) {
  const options = (metrics.filter_options as Record<string, string[]> | undefined) || {};
  const active = (metrics.active_filters as Record<string, string> | undefined) || {};
  const [energy, setEnergy] = useState(active.energy_type || "全部");
  const [category, setCategory] = useState(active.vehicle_category || "全部");
  const [priceBand, setPriceBand] = useState(active.price_band || "全部");
  const [manufacturer, setManufacturer] = useState(active.manufacturer_attribute || "全部");
  const [isApplying, setIsApplying] = useState(false);
  const [applyError, setApplyError] = useState("");

  useEffect(() => {
    setEnergy(active.energy_type || "全部");
    setCategory(active.vehicle_category || "全部");
    setPriceBand(active.price_band || "全部");
    setManufacturer(active.manufacturer_attribute || "全部");
  }, [active.energy_type, active.vehicle_category, active.price_band, active.manufacturer_attribute]);

  function select(label: string, value: string, onChange: (value: string) => void, values: string[] = []) {
    return (
      <label>
        <span>{label}</span>
        <select value={value} onChange={(event) => onChange(event.target.value)}>
          <option value="全部">全部</option>
          {values.filter((item) => item && item !== "全部").map((item) => <option key={item} value={item}>{item}</option>)}
        </select>
      </label>
    );
  }

  async function applyFilters() {
    const parts = [energy, category, priceBand, manufacturer].filter((value) => value && value !== "全部");
    setIsApplying(true);
    setApplyError("");
    try {
      const response = await analyzeMarketReport(
        `打开全国${parts.length ? ` ${parts.join(" ")}` : ""} 新车降价榜`,
        "全国"
      );
      const card = response.market_agent_card || {};
      const summary = (card.summary_report || {}) as Record<string, unknown>;
      onUpdate({
        title: safeText(card.title, "全国新车降价榜"),
        summary: safeText(summary.headline, "已按当前筛选条件刷新全国新车降价榜。"),
        metrics: (card.metrics || {}) as Record<string, unknown>,
        items: Array.isArray(card.recommendations) ? card.recommendations : []
      });
    } catch (error) {
      setApplyError(error instanceof Error ? error.message : "筛选失败，请稍后重试");
    } finally {
      setIsApplying(false);
    }
  }

  return (
    <section className="discount-ranking-filters" aria-label="降价榜筛选">
      {select("能源", energy, setEnergy, options.energy_type)}
      {select("车身", category, setCategory, options.vehicle_category)}
      {select("价格", priceBand, setPriceBand, options.price_band)}
      {select("品牌属性", manufacturer, setManufacturer, options.manufacturer_attribute)}
      <button type="button" onClick={applyFilters} disabled={isApplying}>
        {isApplying ? "正在刷新…" : "应用筛选"}
      </button>
      {applyError ? <small className="inline-error">{applyError}</small> : null}
    </section>
  );
}

function formatMetricDisplay(key: string, value: unknown) {
  if (value === undefined || value === null || value === "") return "-";
  const numeric = numberFromUnknown(value);
  if (["deal_price_low_90d", "deal_price_high_90d"].includes(key) && numeric !== undefined) return formatWan(numeric);
  if (["price_change_7d", "price_change_14d", "price_change_30d", "sell_through_rate", "lead_rate", "inquiry_conversion_rate", "price_volatility"].includes(key) && numeric !== undefined) {
    return formatPercentFromRatio(numeric);
  }
  if (numeric !== undefined && key.includes("cycle")) return `${numeric.toFixed(1).replace(".0", "")} 天`;
  return safeText(value);
}

function formatConfidenceScore(value: unknown) {
  const numeric = numberFromUnknown(value);
  if (numeric === undefined) return "-";
  if (numeric <= 1) return `${Math.round(numeric * 100)}%`;
  return `${Math.round(numeric)}%`;
}

