function formatReportItem(item: string | { question?: string; answer?: string; label?: string; value?: string }) {
  if (!item || typeof item !== "object") return safeText(item);
  if (item.label || item.value) return `${safeText(item.label)}：${safeText(item.value)}`;
  if (item.question || item.answer) return `${safeText(item.question)} ${safeText(item.answer)}`;
  return safeText(item);
}

function decisionToneClass(decision: unknown) {
  const text = safeText(decision);
  if (text.includes("积极") || text.includes("可以")) return "tone-positive";
  if (text.includes("暂缓") || text.includes("复核")) return "tone-danger";
  return "tone-caution";
}

interface PricingCalculatorState {
  key: string;
  systemPurchaseYuan: number;
  systemSaleYuan: number;
  upperYuan: number;
  currentPurchaseInput: string;
  currentSaleInput: string;
  reconInput: string;
  platformInput: string;
  bufferInput: string;
  setCurrentPurchaseInput: (value: string) => void;
  setCurrentSaleInput: (value: string) => void;
  setReconInput: (value: string) => void;
  setPlatformInput: (value: string) => void;
  setBufferInput: (value: string) => void;
  currentPurchaseYuan: number;
  currentSaleYuan: number;
  reconYuan: number;
  platformYuan: number;
  bufferYuan: number;
  priceSpreadYuan: number;
  totalCostYuan: number;
  grossYuan: number;
  grossRate: number;
  saleGuarded: boolean;
  resetToSystem: () => void;
}

function buildPricingExcelPayload(
  result: AgentFinalResult | undefined,
  report: PricingAgentFinalReport,
  slots: Record<string, unknown>,
  calculator: PricingCalculatorState
) {
  return {
    result: (result || {}) as unknown as Record<string, unknown>,
    report: report as unknown as Record<string, unknown>,
    slots,
    calculator: {
      currentPurchaseYuan: calculator.currentPurchaseYuan,
      currentSaleYuan: calculator.currentSaleYuan,
      reconYuan: calculator.reconYuan,
      platformYuan: calculator.platformYuan,
      bufferYuan: calculator.bufferYuan,
      priceSpreadYuan: calculator.priceSpreadYuan,
      totalCostYuan: calculator.totalCostYuan,
      grossYuan: calculator.grossYuan,
      grossRate: calculator.grossRate
    }
  };
}

function usePricingCalculatorState(report?: PricingAgentFinalReport): PricingCalculatorState {
  const key = [
    (report?.price_reasoning as Record<string, unknown> | undefined)?.quote_id,
    report?.vehicle_title,
    report?.point_price_yuan,
    report?.sale_price_yuan,
    report?.upper_yuan
  ].map((item) => safeText(item)).join("|");
  const systemPurchase = getSystemPurchaseYuan(report);
  const saleBase = getSystemSaleYuan(report);
  const guardedSale = systemPurchase > 0 && saleBase > 0 && saleBase < systemPurchase;
  const systemSale = guardedSale ? Math.round(systemPurchase * 1.08) : saleBase;
  const upper = report?.upper_yuan || report?.purchase_price_high_yuan || wanToYuan(report?.purchase_price_high);
  const recon = report?.estimated_recon_cost_yuan || wanToYuan(report?.estimated_recon_cost);
  const platform = report?.platform_service_cost_yuan || wanToYuan(report?.platform_service_cost);
  const buffer = report?.risk_buffer_yuan || wanToYuan(report?.risk_buffer);
  const [currentPurchaseInput, setCurrentPurchaseInput] = useState(formatInputWan(systemPurchase));
  const [currentSaleInput, setCurrentSaleInput] = useState(formatInputWan(systemSale));
  const [reconInput, setReconInput] = useState(formatInputWan(recon));
  const [platformInput, setPlatformInput] = useState(formatInputWan(platform));
  const [bufferInput, setBufferInput] = useState(formatInputWan(buffer));

  useEffect(() => {
    setCurrentPurchaseInput(formatInputWan(systemPurchase));
    setCurrentSaleInput(formatInputWan(systemSale));
    setReconInput(formatInputWan(recon));
    setPlatformInput(formatInputWan(platform));
    setBufferInput(formatInputWan(buffer));
  }, [key]);

  const currentPurchaseYuan = parseCalculatorWan(currentPurchaseInput);
  const currentSaleYuan = parseCalculatorWan(currentSaleInput);
  const reconYuan = parseCalculatorWan(reconInput);
  const platformYuan = parseCalculatorWan(platformInput);
  const bufferYuan = parseCalculatorWan(bufferInput);
  const priceSpreadYuan = currentSaleYuan - currentPurchaseYuan;
  const totalCostYuan = reconYuan + platformYuan + bufferYuan;
  const grossYuan = priceSpreadYuan - totalCostYuan;
  const grossRate = currentSaleYuan > 0 ? grossYuan / currentSaleYuan : 0;

  return {
    key,
    systemPurchaseYuan: systemPurchase,
    systemSaleYuan: systemSale,
    upperYuan: upper,
    currentPurchaseInput,
    currentSaleInput,
    reconInput,
    platformInput,
    bufferInput,
    setCurrentPurchaseInput,
    setCurrentSaleInput,
    setReconInput,
    setPlatformInput,
    setBufferInput,
    currentPurchaseYuan,
    currentSaleYuan,
    reconYuan,
    platformYuan,
    bufferYuan,
    priceSpreadYuan,
    totalCostYuan,
    grossYuan,
    grossRate,
    saleGuarded: guardedSale,
    resetToSystem: () => {
      setCurrentPurchaseInput(formatInputWan(systemPurchase));
      setCurrentSaleInput(formatInputWan(systemSale));
      setReconInput(formatInputWan(recon));
      setPlatformInput(formatInputWan(platform));
      setBufferInput(formatInputWan(buffer));
    }
  };
}

function getSystemPurchaseYuan(report?: PricingAgentFinalReport) {
  return (
    numberFromUnknown(report?.point_price_yuan) ||
    numberFromUnknown(report?.purchase_price_yuan) ||
    wanToYuan(report?.purchase_price) ||
    0
  );
}

function getSystemSaleYuan(report?: PricingAgentFinalReport) {
  const sale = numberFromUnknown(report?.sale_price_yuan) || wanToYuan(report?.sale_price);
  if (sale) return sale;
  const purchase = getSystemPurchaseYuan(report);
  return purchase > 0 ? Math.round(purchase * 1.1) : 0;
}

function formatDeltaWan(current: number, system: number) {
  if (!current || !system) return "";
  const diff = current - system;
  if (Math.abs(diff) < 100) return "与系统建议一致";
  const sign = diff > 0 ? "+" : "-";
  const diffWan = Math.abs(diff) / 10000;
  return `较系统建议 ${sign}${diffWan.toFixed(2).replace(/\.00$/, "")}万`;
}

