function buildInlineDecisionReply(report?: PricingAgentFinalReport) {
  if (!report) return "完整收车价、售车价和利润测算正在生成。";
  const decision = safeText(report.decision_card?.decision || report.decision_summary?.decision, "已给出本车收售价格与最高收车边界");
  const talk = safeText(report.decision_card?.recommended_talk_price || report.decision_summary?.customer_talk_price || formatReportWan(report.point_price_yuan), "建议价附近");
  const cleanDecision = decision.replace(/[。；，,\s]+$/g, "");
  return `${cleanDecision}。先按 ${talk} 开始沟通，完整收车价、售车价和利润测算已生成。`;
}

function formatReportWan(yuanValue?: unknown, wanValue?: unknown) {
  const yuan = numberFromUnknown(yuanValue);
  if (yuan !== undefined) return formatWan(yuan);
  const wan = numberFromUnknown(wanValue);
  if (wan === undefined) return "暂无";
  return `${wan.toFixed(2).replace(/\.00$/, "")}万`;
}

function formatReportWanRange(low?: unknown, high?: unknown) {
  const lower = numberFromUnknown(low);
  const upper = numberFromUnknown(high);
  if (!lower || !upper) return "单点上限";
  return `区间 ${formatReportWan(lower)} - ${formatReportWan(upper)}`;
}

export function formatSignedWan(value?: unknown) {
  const number = numberFromUnknown(value);
  if (number === undefined) return "暂无";
  if (Math.abs(number) < 10000) {
    return `${Math.round(number).toLocaleString("zh-CN")}元`;
  }
  const wan = number / 10000;
  return `${wan.toFixed(2).replace(/\.00$/, "")}万`;
}

function wanToYuan(value?: unknown) {
  const number = numberFromUnknown(value);
  if (!number) return 0;
  return number > 1000 ? number : number * 10000;
}

function formatInputWan(yuanValue?: unknown) {
  const yuan = numberFromUnknown(yuanValue);
  if (!yuan) return "";
  const wan = yuan > 1000 ? yuan / 10000 : yuan;
  return String(Number(wan.toFixed(2)));
}

function parseCalculatorWan(value: string) {
  const number = parseNumberInput(value);
  if (number === undefined) return 0;
  return number < 1000 ? number * 10000 : number;
}

function formatPercentFromRatio(value?: unknown) {
  const number = numberFromUnknown(value);
  if (!number) return "0%";
  const ratio = Math.abs(number) > 1 ? number / 100 : number;
  return `${(ratio * 100).toFixed(1).replace(".0", "")}%`;
}

function formatOptionalPercent(value?: unknown) {
  const number = numberFromUnknown(value);
  if (number === undefined || Number.isNaN(number)) return "-";
  const ratio = Math.abs(number) > 1 ? number / 100 : number;
  return `${(ratio * 100).toFixed(1).replace(".0", "")}%`;
}

function salePriceSourceLabel(source?: unknown) {
  const value = safeText(source);
  if (value === "model") return "售车价来自售车价模型";
  if (value === "model_guarded_floor") return "模型价已做安全底线保护";
  if (value === "fallback_rule") return "业务规则估算";
  return "定价模型与收售价梯度已校验";
}

