function PriceRangeBar({ point, lower, upper }: { point: number; lower: number; upper: number }) {
  if (!point || !lower || !upper || upper <= lower) return null;
  const pointYuan = normalizePriceForScale(point);
  const lowerYuan = normalizePriceForScale(lower);
  const upperYuan = normalizePriceForScale(upper);
  if (upperYuan <= lowerYuan) return null;
  const percentage = Math.max(0, Math.min(100, ((pointYuan - lowerYuan) / (upperYuan - lowerYuan)) * 100));
  return (
    <div className="price-range-bar" aria-label={`价格合理区间 ${formatWan(lower)} 至 ${formatWan(upper)}，建议价 ${formatWan(point)}`}>
      <div className="range-track">
        <div className="range-fill" />
        <div className="range-pointer" style={{ left: `${percentage}%` }}><span>{formatWan(point)}</span></div>
      </div>
      <div className="range-labels"><span>{formatWan(lower)}</span><span>建议价</span><span>{formatWan(upper)}</span></div>
    </div>
  );
}

function normalizePriceForScale(value: number) {
  return value > 1000 ? value : value * 10000;
}

function ConfidenceSegments({ value }: { value: unknown }) {
  const normalized = safeText(value, "-").toUpperCase();
  const active = normalized === "HIGH" ? "high" : normalized === "LOW" ? "low" : "mid";
  return (
    <div className="confidence-segments" aria-label={`估价可信度${confidenceLabel(value)}`}>
      <span className={`segment low ${active === "low" ? "active" : ""}`}>低</span>
      <span className={`segment mid ${active === "mid" ? "active" : ""}`}>中</span>
      <span className={`segment high ${active === "high" ? "active" : ""}`}>高</span>
    </div>
  );
}

function CandidatePriceChart({ candidates, point }: { candidates: Record<string, unknown>[]; point: number }) {
  const rows = candidates.slice(0, 7).map((item, index) => ({
    label: `证据${index + 1}`,
    price: candidatePrice(item)
  })).filter((item) => item.price > 0);
  const max = Math.max(point, ...rows.map((item) => item.price), 1);
  return (
    <div className="candidate-price-chart" aria-label="可比车辆价格分布">
      {rows.map((item) => (
        <div key={item.label}>
          <span>{formatWan(item.price)}</span>
          <i style={{ height: `${Math.max(12, (item.price / max) * 100)}%` }} />
          <small>{item.label}</small>
        </div>
      ))}
      <div className="target-price-bar"><span>{formatWan(point)}</span><i style={{ height: `${Math.max(12, (point / max) * 100)}%` }} /><small>本车估值</small></div>
    </div>
  );
}

function confidenceLabel(value: unknown) {
  const text = safeText(value, "-").toUpperCase();
  return ({ HIGH: "高", MEDIUM: "中", LOW: "低" } as Record<string, string>)[text] || text;
}

function formatRate(value: unknown) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "-";
  const percent = Math.abs(number) <= 1 ? number * 100 : number;
  return `${percent >= 0 ? "+" : ""}${percent.toFixed(1)}%`;
}

function formatDecimal(value: unknown) {
  const number = Number(value);
  return Number.isFinite(number) ? number.toFixed(1).replace(/\.0$/, "") : "-";
}

function joinTextList(value: unknown, fallback: string) {
  return Array.isArray(value) && value.length ? value.map(String).join("；") : fallback;
}

function buildValuationExplanation(result: AgentFinalResult, marketState: Record<string, unknown>) {
  const point = Number(result.metrics?.point_price || 0);
  const lower = Number(result.metrics?.lower || 0);
  const upper = Number(result.metrics?.upper || 0);
  const range = lower && upper ? `${formatWan(lower)}至${formatWan(upper)}` : "当前报价区间";
  return `系统基于车辆七要素与${safeText(result.metrics?.candidate_count, "0")}条可比证据生成建议价，建议以${formatWan(point)}为谈判锚点、${range}为业务边界。${safeText(marketState.market_category_label || marketState.market_category, "行情状态未命中")}只用于风险解释和追价边界，不直接改写点价。`;
}

function buildComparableRows(
  candidates: Record<string, unknown>[],
  comparableEvidence: Record<string, unknown>[],
  point: number
): Record<string, unknown>[] {
  if (comparableEvidence.length) {
    return comparableEvidence.map((item, index) => ({
      ...item,
      candidate_id: item["candidate_id"] || `evidence-${index}`,
      title: item["vehicle"] || item["title"],
      price_yuan: item["price_yuan"] || item["price"],
      impact: item["impact"] || candidateBusinessValue(item, point)
    }));
  }
  return candidates;
}

function candidateTierLabel(value: unknown) {
  const key = safeText(value, "").toLowerCase();
  const labels: Record<string, string> = {
    same_trim_year: "同款型同年款",
    same_trim_any_year: "同款型跨年款",
    same_series_year: "同车系同年款",
    same_series_any_year: "同车系跨年款",
    same_trim_year_sparse: "同款型同年款（稀疏样本）",
    same_trim_any_year_sparse: "同款型跨年款（稀疏样本）",
    same_series_year_sparse: "同车系同年款（稀疏样本）",
    same_series_any_year_sparse: "同车系跨年款（稀疏样本）",
    l0: "严格同款同年",
    l1: "同款近年款",
    l2: "同车系同年款",
    l2_wide_exact_trim: "同款扩展样本",
    l3: "同车系相邻款型",
    l4: "同配置跨年款",
    same_trim: "同款型",
    strict_comparable: "严格可比",
    adjacent: "相邻款型",
    local_historical: "本地历史成交"
  };
  return labels[key] || (key.includes("same_series") ? "同车系同年款" : key.includes("trim") ? "同款型" : "同车系可比");
}

function candidateCondition(item: Record<string, unknown>) {
  const parts = [
    item.city,
    item.model_year ? `${safeText(item.model_year)}款` : undefined,
    item.mileage_wan_km || item.mileage ? `${safeText(item.mileage_wan_km || item.mileage)}万公里` : undefined,
    item.transfer_count !== undefined ? `${safeText(item.transfer_count)}次过户` : undefined
  ].filter(Boolean);
  return parts.length ? parts.map(String).join(" · ") : "车况字段以证据库为准";
}

function candidateBusinessValue(item: Record<string, unknown>, point: number) {
  const price = candidatePrice(item);
  if (!price || !point) return "用于补充同车系价格分布";
  if (item.used_for_point_baseline === false && item.used_for_interval) return "只界定报价区间，不参与点价";
  const delta = ((price / point) - 1) * 100;
  if (Math.abs(delta) <= 3) return "贴近估值锚点，支持当前点价";
  return delta > 0 ? `高于锚点 ${delta.toFixed(1)}%，定义价格上沿` : `低于锚点 ${Math.abs(delta).toFixed(1)}%，定义价格下沿`;
}

function candidatePrice(item: Record<string, unknown>) {
  return Number(item.price_yuan || item.converted_c2b_price || item.c2b_price || item.price || item.b2c_price || 0);
}

function ResultActions({
  actions,
  onLocalAction
}: {
  actions: string[];
  onLocalAction?: (action: string) => boolean;
}) {
  const { sendTurn } = useAgentTurn();
  const activeModule = useAgentStore((state) => state.activeModule);

  function handleAction(action: string) {
    if (onLocalAction?.(action)) return;
    if (action.includes("表格")) {
      window.dispatchEvent(new CustomEvent("agent:open-pricing-form"));
      return;
    }
    if (action.includes("候选")) {
      window.dispatchEvent(new CustomEvent("agent:show-pricing-evidence"));
      return;
    }
    if (action.includes("解释") || action.includes("为什么")) {
      window.dispatchEvent(new CustomEvent("agent:show-price-explanation"));
      return;
    }
    if (action.includes("修改")) {
      window.dispatchEvent(new CustomEvent("agent:open-pricing-form"));
      return;
    }
    if (action.includes("补充") || action.includes("选择具体款型") || action.includes("车辆信息")) {
      window.dispatchEvent(new CustomEvent("agent:open-pricing-form"));
      return;
    }
    if (action.includes("估价")) {
      sendTurn(action, { module: "pricing" });
      return;
    }
    sendTurn(action, { module: activeModule });
  }

  return (
    <div className="result-actions">
      {actions.map((action) => (
        <button key={action} type="button" onClick={() => handleAction(action)}>
          {action.includes("候选") ? <FileSearch size={14} /> : action.includes("解释") || action.includes("为什么") ? <Info size={14} /> : action.includes("导出") ? <Copy size={14} /> : <Download size={14} />}
          {action}
        </button>
      ))}
    </div>
  );
}

