import { LogIn } from "lucide-react";
import { createContext, type ReactNode, useContext, useEffect, useState } from "react";
import {
  fetchInternalAuthStatus,
  loginInternalUser,
  type InternalAuthStatus
} from "../../api/agentClient";

const InternalAuthContext = createContext<InternalAuthStatus>({ enabled: false, authenticated: true });

export function useInternalAuth() {
  return useContext(InternalAuthContext);
}

export function InternalAuthGate({ children }: { children: ReactNode }) {
  const [status, setStatus] = useState<InternalAuthStatus>({ enabled: false, authenticated: true });
  const [username, setUsername] = useState("dcar_internal");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (import.meta.env.MODE === "test") return;
    let active = true;
    fetchInternalAuthStatus()
      .then((next) => active && setStatus(next))
      .catch(() => active && setStatus({ enabled: true, authenticated: false }));
    return () => { active = false; };
  }, []);

  useEffect(() => {
    function requireAuthentication() {
      setStatus({ enabled: true, authenticated: false });
      setPassword("");
      setError("登录状态已失效，请重新登录");
    }
    window.addEventListener("agent:authentication-required", requireAuthentication);
    return () => window.removeEventListener("agent:authentication-required", requireAuthentication);
  }, []);

  if (!status.enabled || status.authenticated) {
    return <InternalAuthContext.Provider value={status}>{children}</InternalAuthContext.Provider>;
  }

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    setSubmitting(true);
    setError("");
    try {
      setStatus(await loginInternalUser(username.trim(), password));
      setPassword("");
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "登录失败，请重试");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <main className="internal-login-page">
      <section className="internal-login-card">
        <div className="internal-login-mark" aria-hidden="true">懂</div>
        <p className="internal-login-kicker">AI 懂车价 · 内部灰度测试</p>
        <h1>登录后开始测试</h1>
        <p className="internal-login-note">账号仅用于记录测试人员、问题上下文和反馈，不影响业务数据。</p>
        <form onSubmit={submit}>
          <label>
            <span>账号</span>
            <input value={username} onChange={(event) => setUsername(event.target.value)} autoComplete="username" />
          </label>
          <label>
            <span>密码</span>
            <input type="password" value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="current-password" autoFocus />
          </label>
          {error ? <p className="internal-login-error" role="alert">{error}</p> : null}
          <button type="submit" disabled={submitting || !username.trim() || !password}>
            <LogIn size={18} /> {submitting ? "正在登录…" : "进入 AI 懂车价"}
          </button>
        </form>
      </section>
    </main>
  );
}
