import { useEffect, useMemo, useState } from "react";
import { fetchSelectionStrategyAblation } from "../../api/agentClient";

type StrategyRow = {
  strategy_name?: string;
  used_signals?: string[];
  metrics?: Record<string, number | string | null | undefined>;
  recommend_pass?: Record<string, boolean>;
  scale_pass?: Record<string, boolean>;
  strategy_score?: number;
  topk_evaluation?: Record<string, Record<string, number | string | null | undefined>>;
};

function formatNumber(value: unknown, digits = 1) {
  if (value === null || value === undefined || value === "") return "-";
  const number = Number(value);
  if (!Number.isFinite(number)) return String(value);
  return new Intl.NumberFormat("zh-CN", { maximumFractionDigits: digits }).format(number);
}

function formatRate(value: unknown) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "-";
  return `${(number * 100).toFixed(1)}%`;
}

export function SelectionStrategyLab() {
  const [report, setReport] = useState<Record<string, any> | null>(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let mounted = true;
    fetchSelectionStrategyAblation()
      .then((data) => {
        if (mounted) setReport(data);
      })
      .catch((err) => {
        if (mounted) setError(err instanceof Error ? err.message : String(err));
      })
      .finally(() => {
        if (mounted) setLoading(false);
      });
    return () => {
      mounted = false;
    };
  }, []);

  const rows = useMemo(() => {
    return ((report?.strategy_results || []) as StrategyRow[]).filter((item) => item.strategy_name !== "baseline_all");
  }, [report]);

  const final = report?.final_recommendation || {};
  const dsi = report?.dsi_increment || {};
  const ranking = report?.ranking_increment || {};

  return (
    <main className="selection-lab-page">
      <header className="selection-lab-header">
        <div>
          <p className="hero-kicker">Selection Strategy Lab</p>
          <h1>选品策略对照回测</h1>
          <p>内部评估页，只用于验证行情/事件/DSI/排行榜信号组合，不展示给一线业务员。</p>
        </div>
        <a className="lab-back-link" href="/agent">返回 Agent</a>
      </header>

      {loading ? <section className="selection-lab-panel">正在读取策略实验报告...</section> : null}
      {error ? <section className="selection-lab-panel lab-error">{error}</section> : null}

      {report ? (
        <>
          <section className="selection-lab-summary">
            <div>
              <span>建议 P0 策略</span>
              <strong>{final.strategy_name || "-"}</strong>
              <small>{(final.used_signals || []).join(" / ")}</small>
            </div>
            <div>
              <span>综合分</span>
              <strong>{formatNumber(final.strategy_score, 1)}</strong>
              <small>效率 + 规模 + 转化</small>
            </div>
            <div>
              <span>DSI 增益</span>
              <strong>{formatNumber(dsi.strategy_score_delta, 2)}</strong>
              <small>{dsi.is_positive ? "正增益" : "未证明正增益"}</small>
            </div>
            <div>
              <span>排行榜增益</span>
              <strong>{formatNumber(ranking.strategy_score_delta, 2)}</strong>
              <small>{ranking.is_positive ? "正增益" : "未证明正增益"}</small>
            </div>
          </section>

          <section className="selection-lab-panel">
            <div className="lab-panel-head">
              <h2>策略对比</h2>
              <span>{report.generated_at}</span>
            </div>
            <div className="selection-lab-table-wrap">
              <table className="selection-lab-table">
                <thead>
                  <tr>
                    <th>策略</th>
                    <th>信号</th>
                    <th>选中率</th>
                    <th>总利润</th>
                    <th>利润保留</th>
                    <th>均利</th>
                    <th>成交周期</th>
                    <th>收车转化</th>
                    <th>售车转化</th>
                    <th>Top20 总利润</th>
                    <th>结论</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row) => {
                    const metrics = row.metrics || {};
                    const top20 = row.topk_evaluation?.top20 || {};
                    const pass = row.recommend_pass?.all_pass && row.scale_pass?.all_pass;
                    return (
                      <tr key={row.strategy_name}>
                        <td>{row.strategy_name}</td>
                        <td>{(row.used_signals || []).join(" / ")}</td>
                        <td>{formatRate(metrics.selection_rate)}</td>
                        <td>{formatNumber(metrics.selected_total_profit, 0)}</td>
                        <td>{formatRate(metrics.profit_retention_rate)}</td>
                        <td>{formatNumber(metrics.avg_profit, 0)}</td>
                        <td>{formatNumber(metrics.avg_days_to_sell, 1)}</td>
                        <td>{formatRate(metrics.acquisition_conversion_rate)}</td>
                        <td>{formatRate(metrics.sales_conversion_rate)}</td>
                        <td>{formatNumber(top20.total_profit, 0)}</td>
                        <td><span className={pass ? "lab-pass" : "lab-fail"}>{pass ? "可进 P0" : "需约束"}</span></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </section>

          <section className="selection-lab-panel">
            <div className="lab-panel-head">
              <h2>错误分析</h2>
              <span>只展示前 10 条高价值样本</span>
            </div>
            <div className="lab-error-grid">
              {Object.entries(report.error_analysis || {}).map(([name, items]) => (
                <div key={name} className="lab-error-card">
                  <h3>{name}</h3>
                  {(items as Record<string, unknown>[]).slice(0, 10).map((item, index) => (
                    <p key={`${name}-${index}`}>
                      {item.city as string} {item.brand as string} {item.series as string}
                      <span>均利 {formatNumber(item.avg_profit, 0)} · 周期 {formatNumber(item.avg_days_to_sell, 1)}</span>
                    </p>
                  ))}
                </div>
              ))}
            </div>
          </section>
        </>
      ) : null}
    </main>
  );
}
