import { BarChart3, Edit3, Newspaper, Sparkles, TrendingDown, TriangleAlert } from "lucide-react";
import { useAgentTurn } from "../../hooks/useAgentTurn";
import { useAgentStore } from "../../store/agentStore";
import type { BusinessModule } from "../../types/agent";

const commands: Record<BusinessModule, Array<{ label: string; message: string; icon: typeof Sparkles }>> = {
  selection: [
    { label: "推荐值得收", message: "推荐值得收的车系", icon: Sparkles },
    { label: "风险车系", message: "这个城市哪些车系不要收", icon: TriangleAlert },
    { label: "低价机会", message: "20万以内有什么机会", icon: TrendingDown }
  ],
  market: [
    { label: "今日日报", message: "给我今天的行业日报", icon: Newspaper },
    { label: "全国行情", message: "打开今天的全国二手车行情研判", icon: BarChart3 },
    { label: "降价最多", message: "打开全国新车降价榜", icon: TrendingDown }
  ],
  pricing: []
};

interface QuickCommandBarProps {
  activeModule: BusinessModule;
}

export function QuickCommandBar({ activeModule }: QuickCommandBarProps) {
  const { sendTurn, isPending } = useAgentTurn();
  const currentPricingResult = useAgentStore((state) => state.currentPricingResult);
  const activeCommands =
    activeModule === "pricing"
      ? [
          { label: currentPricingResult ? "修改参数" : "填写车辆信息", message: "打开车辆信息表格", icon: Edit3, disabled: false }
        ]
      : commands[activeModule].map((command) => ({ ...command, disabled: false }));
  return (
    <section className="quick-command-bar" aria-label="快捷任务">
      {activeCommands.map((command) => {
        const Icon = command.icon;
        return (
          <button
            key={command.label}
            type="button"
            className={activeCommands.indexOf(command) === 0 ? "quick-chip primary" : "quick-chip secondary"}
            disabled={isPending || command.disabled}
            onClick={() => {
              if (command.label === "填写车辆信息" || command.label === "修改参数") {
                window.dispatchEvent(new CustomEvent("agent:open-pricing-form"));
                return;
              }
              sendTurn(command.message, {
                module: activeModule,
                payload: activeModule === "market" ? { selected_city: "全国" } : undefined
              });
            }}
          >
            <Icon size={16} />
            {command.label}
          </button>
        );
      })}
    </section>
  );
}
