import { create } from "zustand";
import type {
  AgentClientState,
  BusinessModule,
  ChatMessage,
  DailyReportContext,
  PricingResult
} from "../types/agent";
import { newId, nowIso } from "../utils/format";

interface AgentStore {
  sessionId: string;
  activeModule: BusinessModule;
  selectedCity: string;
  selectedVehicleCategory: string;
  selectedEnergyType: string;
  selectedBodyType: string;
  messages: ChatMessage[];
  clientState: AgentClientState;
  currentPricingResult?: PricingResult;
  lastDailyReportContext?: DailyReportContext;
  setModule: (module: BusinessModule) => void;
  setCity: (city: string) => void;
  setVehicleCategory: (category: string) => void;
  setEnergyType: (energyType: string) => void;
  setBodyType: (bodyType: string) => void;
  addMessage: (message: Omit<ChatMessage, "id" | "createdAt"> & Partial<Pick<ChatMessage, "id" | "createdAt">>) => string;
  updateMessage: (
    id: string,
    updater: Partial<ChatMessage> | ((message: ChatMessage) => Partial<ChatMessage>)
  ) => void;
  mergeClientState: (patch: Partial<AgentClientState>) => void;
  setPricingResult: (result?: PricingResult) => void;
  setDailyReportContext: (context?: DailyReportContext) => void;
}

const initialSessionId = `agent_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;

function isBusinessModule(value: unknown): value is BusinessModule {
  return value === "selection" || value === "market" || value === "pricing";
}

export const useAgentStore = create<AgentStore>((set, get) => ({
  sessionId: initialSessionId,
  activeModule: "pricing",
  selectedCity: "全国",
  selectedVehicleCategory: "全部",
  selectedEnergyType: "全部",
  selectedBodyType: "全部",
  messages: [],
  clientState: {
    module: "pricing",
    selectedBusinessModule: "pricing",
    selectedCity: "全国",
    selectedVehicleCategory: "全部",
    selectedEnergyType: "全部",
    selectedBodyType: "全部"
  },
  setModule: (module) =>
    set((state) => ({
      activeModule: module,
      clientState: {
        ...state.clientState,
        module,
          selectedBusinessModule: module
      }
    })),
  setCity: (city) =>
    set((state) => ({
      selectedCity: city,
      clientState: {
        ...state.clientState,
        selectedCity: city
      }
    })),
  setVehicleCategory: (category) =>
    set((state) => ({
      selectedVehicleCategory: category,
      selectedBodyType: ["轿车", "SUV", "MPV", "全部"].includes(category) ? category : state.selectedBodyType,
      selectedEnergyType: ["新能源", "燃油车"].includes(category) ? category : state.selectedEnergyType,
      clientState: {
        ...state.clientState,
        selectedVehicleCategory: category,
        selectedBodyType: ["轿车", "SUV", "MPV", "全部"].includes(category) ? category : state.selectedBodyType,
        selectedEnergyType: ["新能源", "燃油车"].includes(category) ? category : state.selectedEnergyType
      }
    })),
  setEnergyType: (energyType) =>
    set((state) => ({
      selectedEnergyType: energyType,
      clientState: {
        ...state.clientState,
        selectedEnergyType: energyType
      }
    })),
  setBodyType: (bodyType) =>
    set((state) => ({
      selectedBodyType: bodyType,
      selectedVehicleCategory: bodyType,
      clientState: {
        ...state.clientState,
        selectedBodyType: bodyType,
        selectedVehicleCategory: bodyType
      }
    })),
  addMessage: (message) => {
    const id = message.id || newId("msg");
    const createdAt = message.createdAt || nowIso();
    set((state) => ({
      messages: [
        ...state.messages,
        {
          ...message,
          id,
          createdAt
        }
      ].slice(-100)
    }));
    return id;
  },
  updateMessage: (id, updater) =>
    set((state) => ({
      messages: state.messages.map((message) => {
        if (message.id !== id) return message;
        const patch = typeof updater === "function" ? updater(message) : updater;
        return { ...message, ...patch };
      })
    })),
  mergeClientState: (patch) =>
    set((state) => {
      const nextModule = isBusinessModule(patch.module)
        ? patch.module
        : isBusinessModule(patch.selectedBusinessModule)
          ? patch.selectedBusinessModule
          : state.activeModule;
      const nextCity =
        typeof patch.selectedCity === "string" && patch.selectedCity.trim()
          ? patch.selectedCity
          : state.selectedCity;
      const nextCategory =
        typeof patch.selectedVehicleCategory === "string" && patch.selectedVehicleCategory.trim()
          ? patch.selectedVehicleCategory
          : state.selectedVehicleCategory;
      const nextEnergy =
        typeof patch.selectedEnergyType === "string" && patch.selectedEnergyType.trim()
          ? patch.selectedEnergyType
          : state.selectedEnergyType;
      const nextBody =
        typeof patch.selectedBodyType === "string" && patch.selectedBodyType.trim()
          ? patch.selectedBodyType
          : state.selectedBodyType;
      return {
        activeModule: nextModule,
        selectedCity: nextCity,
        selectedVehicleCategory: nextCategory,
        selectedEnergyType: nextEnergy,
        selectedBodyType: nextBody,
        clientState: {
          ...state.clientState,
          ...patch,
          module: nextModule,
          selectedBusinessModule: nextModule,
          selectedCity: nextCity,
          selectedVehicleCategory: nextCategory,
          selectedEnergyType: nextEnergy,
          selectedBodyType: nextBody
        }
      };
    }),
  setPricingResult: (result) =>
    set((state) => ({
      currentPricingResult: result,
      clientState: {
        ...state.clientState,
        current_pricing_result: result
      }
    })),
  setDailyReportContext: (context) =>
    set((state) => ({
      lastDailyReportContext: context,
      clientState: {
        ...state.clientState,
        lastDailyReportContext: context
      }
    }))
}));

export function buildTurnClientState(): AgentClientState {
  const state = useAgentStore.getState();
  return {
    ...state.clientState,
    module: state.activeModule,
    selectedBusinessModule: state.activeModule,
    selectedCity: state.selectedCity,
    selectedVehicleCategory: state.selectedVehicleCategory,
    selectedEnergyType: state.selectedEnergyType,
    selectedBodyType: state.selectedBodyType
  };
}
