import { Download, RefreshCw } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import {
  fetchInternalFeedbackRecords,
  fetchInternalFeedbackStats,
  type InternalFeedbackRecord,
  type InternalFeedbackStats
} from "../../api/agentClient";
import { useInternalAuth } from "../layout/InternalAuthGate";

const MODULE_LABEL: Record<string, string> = { selection: "选品", market: "行情", pricing: "定价", market_state: "行情/选品", media_pricing: "定价" };

export function FeedbackAdminPage() {
  const auth = useInternalAuth();
  const [stats, setStats] = useState<InternalFeedbackStats | null>(null);
  const [records, setRecords] = useState<InternalFeedbackRecord[]>([]);
  const [module, setModule] = useState("");
  const [rating, setRating] = useState("");
  const [loading, setLoading] = useState(false);

  const query = useMemo(() => {
    const params = new URLSearchParams({ limit: "200" });
    if (module) params.set("module", module);
    if (rating) params.set("rating", rating);
    return params.toString();
  }, [module, rating]);

  async function load() {
    setLoading(true);
    try {
      const [nextStats, nextRecords] = await Promise.all([
        fetchInternalFeedbackStats(),
        fetchInternalFeedbackRecords(query)
      ]);
      setStats(nextStats);
      setRecords(nextRecords.records);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { void load(); }, [query]);

  if (!auth.can_view_feedback) {
    return (
      <main className="feedback-admin-page">
        <section className="feedback-empty">
          <h1>仅管理员可查看反馈后台</h1>
          <p>当前账号可以继续提交反馈，但不能查看其他测试人员的记录。</p>
          <a href="/agent">返回 Agent</a>
        </section>
      </main>
    );
  }

  return (
    <main className="feedback-admin-page">
      <header className="feedback-admin-header">
        <div><p>AI 懂车价 · 内部灰度</p><h1>反馈记录后台</h1><span>每条反馈都已关联用户原问题、当时上下文、系统回答和发布版本。</span></div>
        <nav><a href="/agent">返回 Agent</a><a href="/api/internal-feedback/export.csv"><Download size={16} /> 导出 CSV</a><button onClick={() => void load()} disabled={loading}><RefreshCw size={16} /> 刷新</button></nav>
      </header>
      <section className="feedback-stat-grid">
        <article><span>反馈总数</span><strong>{stats?.total ?? 0}</strong></article>
        <article><span>正向</span><strong>{stats?.positive ?? 0}</strong></article>
        <article><span>负向</span><strong>{stats?.negative ?? 0}</strong></article>
        <article><span>测试用户</span><strong>{stats?.users ?? 0}</strong></article>
        <article><span>已记录交互</span><strong>{stats?.interactions ?? 0}</strong></article>
      </section>
      <section className="feedback-admin-filters">
        <select value={module} onChange={(event) => setModule(event.target.value)}><option value="">全部模块</option><option value="selection">选品</option><option value="market">行情</option><option value="pricing">定价</option></select>
        <select value={rating} onChange={(event) => setRating(event.target.value)}><option value="">全部评价</option><option value="1">有帮助</option><option value="0">文字建议</option><option value="-1">没帮助</option></select>
        <span>{loading ? "正在读取…" : `当前显示 ${records.length} 条`}</span>
      </section>
      <section className="feedback-record-list">
        {records.map((record) => (
          <details key={record.feedback_id} className={`feedback-record rating-${record.rating}`}>
            <summary>
              <span className="feedback-rating-badge">{record.rating > 0 ? "有帮助" : record.rating < 0 ? "没帮助" : "建议"}</span>
              <strong>{record.user_question || "未记录问题"}</strong>
              <span>{MODULE_LABEL[record.module] || record.module}</span>
              <time>{record.created_at}</time>
            </summary>
            <div className="feedback-record-detail">
              <p><b>测试人员：</b>{record.username}　<b>版本：</b>{record.release_version || "-"}</p>
              <p><b>反馈内容：</b>{record.comment || "未填写文字反馈"}</p>
              <h3>问题发生时的上下文</h3><pre>{JSON.stringify(record.request_context || {}, null, 2)}</pre>
              <h3>当时的系统回答</h3><pre>{JSON.stringify(record.response_context || {}, null, 2)}</pre>
            </div>
          </details>
        ))}
        {!records.length && !loading ? <p className="feedback-empty">还没有符合条件的反馈。</p> : null}
      </section>
    </main>
  );
}
