function handleAuthenticationRequired(response: Response, url: string): void {
  if (response.status !== 401 || url.includes("/api/auth/login")) return;
  window.dispatchEvent(new CustomEvent("agent:authentication-required"));
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    headers: {
      "Content-Type": "application/json",
      ...(init?.headers || {})
    },
    ...init
  });
  handleAuthenticationRequired(response, url);
  const text = await response.text();
  const data = text ? JSON.parse(text) : {};
  if (!response.ok || data.success === false) {
    throw new Error(data.error || `${response.status} ${response.statusText}`);
  }
  return data as T;
}

