export async function streamInteractionTurn(
  payload: TurnPayload,
  onEvent: (event: AgentStreamEvent) => void,
  signal?: AbortSignal
): Promise<InteractionTurnResponse> {
  const response = await fetch("/api/interaction/turn/stream", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/x-ndjson"
    },
    body: JSON.stringify(payload),
    signal
  });
  handleAuthenticationRequired(response, "/api/interaction/turn/stream");
  if (!response.ok || !response.body) {
    const data = await response.json().catch(() => ({}));
    throw new Error(data.error || `${response.status} ${response.statusText}`);
  }
  const contentType = response.headers.get("Content-Type") || "";
  if (!contentType.includes("application/x-ndjson")) {
    const data = await response.json() as InteractionTurnResponse | { data?: InteractionTurnResponse; error?: string };
    const finalResponse = "data" in data && data.data ? data.data : data as InteractionTurnResponse;
    if (!finalResponse || ("error" in data && data.error)) {
      throw new Error(("error" in data && data.error) || "Agent 请求失败");
    }
    onEvent({ event_type: "turn.completed", response: finalResponse });
    return finalResponse;
  }
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let finalResponse: InteractionTurnResponse | undefined;
  let lastVisibleEventAt = 0;
  const detailStreamedSteps = new Set<string>();

  async function deliver(event: AgentStreamEvent) {
    const minimumGap = minimumVisibleEventGap(event.event_type);
    if (minimumGap > 0 && lastVisibleEventAt > 0) {
      const elapsed = Date.now() - lastVisibleEventAt;
      if (elapsed < minimumGap) {
        await waitForVisibleEvent(minimumGap - elapsed, signal);
      }
    }
    onEvent(event);
    if (event.event_type !== "heartbeat") lastVisibleEventAt = Date.now();
    if (event.event_type === "turn.failed") {
      throw new Error(event.error || "Agent 任务执行失败");
    }
    if (event.event_type === "turn.completed" && event.response) {
      if (event.response.pricing_agent) {
        event.response.pricing_agent.streaming = {
          ...(event.response.pricing_agent.streaming || {}),
          mode: "reveal_all"
        };
      }
      finalResponse = event.response;
    }
  }

  async function consume(line: string) {
    if (!line.trim()) return;
    const event = JSON.parse(line) as AgentStreamEvent;
    const stepKey = event.step ? String(event.step.step_id || event.step.name || "") : "";
    if (event.event_type === "tool.delta" && stepKey) detailStreamedSteps.add(stepKey);
    if (event.event_type === "tool.completed" && event.step?.business_explanation && stepKey && !detailStreamedSteps.has(stepKey)) {
      const explanation = event.step.business_explanation;
      for (const field of ["conclusion", "evidence", "chips", "impact", "action", "risk"] as const) {
        const value = explanation[field];
        if (value === undefined || value === null || value === "" || (Array.isArray(value) && !value.length)) continue;
        await deliver({
          event_type: "tool.delta",
          task_id: event.task_id,
          module: event.module,
          at: event.at,
          step: {
            step_id: event.step.step_id,
            name: event.step.name,
            status: "running",
            business_explanation: { [field]: value }
          }
        });
      }
      detailStreamedSteps.add(stepKey);
    }
    await deliver(event);
  }

  while (true) {
    const { done, value } = await reader.read();
    buffer += decoder.decode(value || new Uint8Array(), { stream: !done });
    const lines = buffer.split("\n");
    buffer = lines.pop() || "";
    for (const line of lines) await consume(line);
    if (done) break;
  }
  if (buffer.trim()) await consume(buffer);
  if (!finalResponse) throw new Error("Agent 事件流结束，但没有收到最终结果");
  return finalResponse;
}

function minimumVisibleEventGap(eventType: AgentStreamEvent["event_type"]): number {
  switch (eventType) {
    case "intent.classified":
      return 140;
    case "plan.ready":
      return 120;
    case "plan.delta":
      return 80;
    case "tool.started":
      return 120;
    case "tool.delta":
      return 75;
    case "tool.completed":
      return 160;
    case "turn.completed":
      return 100;
    default:
      return 0;
  }
}

function waitForVisibleEvent(delayMs: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(new DOMException("Agent 请求已取消", "AbortError"));
      return;
    }
    const timer = window.setTimeout(resolve, delayMs);
    signal?.addEventListener(
      "abort",
      () => {
        window.clearTimeout(timer);
        reject(new DOMException("Agent 请求已取消", "AbortError"));
      },
      { once: true }
    );
  });
}

export async function searchVehicleCatalog(
  query: string,
  limit = 12,
  signal?: AbortSignal
): Promise<VehicleSearchItem[]> {
  if (!query.trim()) return [];
  const params = new URLSearchParams({ q: query, limit: String(limit) });
  const data = await requestJson<{ success: boolean; results?: VehicleSearchItem[]; items?: VehicleSearchItem[] }>(
    `/api/car-models/search?${params.toString()}`,
    { signal }
  );
  return data.results || data.items || [];
}

