function priceRoleMeaning(value: unknown) {
  return ({
    purchase_price: "生成预计实际收车价和最高收车价",
    listing_price: "生成建议挂牌价和预计实际售卖价",
    market_value: "生成完整挂牌、售卖和收车价格",
    unknown_price: "先确认需要哪类价格",
    no_price: "回答汽车业务问题"
  } as Record<string, string>)[String(value || "")] || "按用户问题选择对应业务能力";
}

function humanizeExecutionDetail(name: string, detail: string) {
  const clean = detail
    .replace(/cohort\s*=\s*(\d+)/gi, "可比较车系年款组合 $1 个")
    .replace(/DSI/gi, "供需指数")
    .replace(/\//g, "、")
    .trim();
  if (!clean) return `${name}已完成。`;
  if (/^\d{4}-\d{2}-\d{2}$/.test(clean)) return `已读取 ${clean} 行业日报，作为本轮市场背景。`;
  return clean;
}

function toolStatus(status: string): AgentExecutionStep["status"] {
  if (["success", "reused_context", "done"].includes(status)) return "done";
  if (["blocked", "failed"].includes(status)) return "blocked";
  if (["skipped", "not_required", "not_loaded", "available_as_context", "not_run"].includes(status)) return "skipped";
  return "running";
}

function buildToolDetail(
  name: string,
  result: Record<string, unknown>,
  selectedCity: string,
  selectedVehicleCategory: string,
  tool: Record<string, unknown>
) {
  const duration = Number(tool.duration_ms || 0);
  const audit = duration ? `真实执行 ${duration.toFixed(0)}ms` : "后端已执行";
  const rawStatus = String(tool.status || "");
  const warnings = Array.isArray(tool.warnings) ? tool.warnings.map(String).filter(Boolean) : [];
  if (name === "意图识别") {
    const role = priceRoleMeaning(result.price_role);
    return `已判断本次任务：${role}；${decisionLabel(result.decision)}；${audit}。`;
  }
  if (name === "抽取车辆字段") {
    const slots = (result.recognized_slots || {}) as Record<string, unknown>;
    const recognized = summarizeVehicleSlots(slots);
    return recognized ? `已识别：${recognized}；${audit}。` : `未识别到可用于估价的车辆七要素；${audit}。`;
  }
  if (name === "七要素校验") {
    const missing = Array.isArray(result.missing_fields) ? (result.missing_fields as unknown[]).map((field) => slotLabel(String(field))).join("、") : "";
    return missing ? `缺失：${missing}；定价模型未启动；${audit}。` : `七要素完整，可以调用定价模型生成收售价格；${audit}。`;
  }
  if (["skipped", "not_required", "not_loaded"].includes(rawStatus)) {
    return `${warnings.join("；") || "工具已真实执行，但当前范围没有可用结果"}；${audit}。`;
  }
  if (["failed", "blocked"].includes(rawStatus)) {
    return `${warnings.join("；") || "当前步骤未能完成，请检查所需信息"}；${audit}。`;
  }
  if (name === "读取行情指标") {
    const input = (tool.input || {}) as Record<string, unknown>;
    const metrics = (result.metrics || {}) as Record<string, unknown>;
    const series = safeLabel(result.series || metrics.series || input.series || selectedVehicleCategory);
    const city = safeLabel(result.city || metrics.city || input.city || selectedCity);
    const samples = safeLabel(metrics.deal_sample_90d || metrics.deal_count, "");
    const inventory = safeLabel(metrics.listing_count || metrics.current_inventory, "");
    const cycle = safeLabel(metrics.avg_deal_cycle || metrics.inventory_cycle, "");
    const hit = result.matched_rows ? `命中 ${result.matched_rows} 条车型+城市行情` : "未命中精确车型+城市行情";
    const signals = [
      samples ? `有效成交证据 ${samples} 条` : "",
      inventory ? `当前在售 ${inventory}` : "",
      cycle ? `周转/成交周期约 ${formatCompactNumber(cycle)} 天` : "",
    ].filter(Boolean).join("；");
    return `对象：${series}；城市：${city}；${hit}${signals ? `；${signals}` : ""}；${audit}。`;
  }
  if (name === "判断行情状态") {
    const reasons = compactList(result.reasons, 2);
    const risks = compactList(result.risks, 2);
    return [
      `状态：${safeLabel(result.market_category_label || result.market_category)}`,
      `建议：${safeLabel(result.recommendation_label || result.action, "结合单车复核")}`,
      reasons ? `依据：${reasons}` : "",
      risks ? `风险：${risks}` : "",
      audit,
    ].filter(Boolean).join("；") + "。";
  }
  if (name === "生成推荐清单") return `已整理 ${Array.isArray(result.recommendations) ? result.recommendations.length : 0} 个候选结果。`;
  if (name === "调用估价模型" || name === "调用定价模型") {
    const priceObj = (result.price || {}) as Record<string, unknown>;
    const explanation = (result.business_explanation || {}) as Record<string, unknown>;
    const conclusion = (explanation.conclusion || {}) as Record<string, unknown>;
    const evidence = Array.isArray(result.selected_comparables)
      ? result.selected_comparables
      : Array.isArray(explanation.evidence_details)
        ? explanation.evidence_details
        : [];
    const finalPrice = result.final_price || priceObj.point || conclusion.reference_price_wan;
    const interval = Array.isArray(conclusion.interval_wan)
      ? `${formatToolWan(conclusion.interval_wan[0])}-${formatToolWan(conclusion.interval_wan[1])}`
      : priceObj.lower && priceObj.upper
        ? `${formatToolWan(priceObj.lower)}-${formatToolWan(priceObj.upper)}`
        : "";
    return [
      finalPrice ? `定价模型收车参考：${formatToolWan(finalPrice)}` : "定价模型未产生新价格",
      interval ? `业务区间：${interval}` : "",
      `置信度：${safeLabel(result.confidence || conclusion.confidence)}`,
      `可比证据：${evidence.length} 条`,
      audit,
    ].filter(Boolean).join("；") + "。";
  }
  if (name === "融合日报事件") {
    const conclusions = compactList(result.core_conclusions, 1, 96);
    const evidence = Array.isArray(result.evidence) ? result.evidence : [];
    const firstEvidence = evidence[0] && typeof evidence[0] === "object" ? shortText((evidence[0] as Record<string, unknown>).text, 90) : "";
    return [
      `日报：${safeLabel(result.report_id || result.filename, "未加载日报")}`,
      result.report_date ? `日期：${result.report_date}` : "",
      evidence.length ? `融合 ${evidence.length} 条相关证据` : "",
      conclusions ? `摘要：${conclusions}` : "",
      firstEvidence ? `证据片段：${firstEvidence}` : "",
      audit,
    ].filter(Boolean).join("；") + "。";
  }
  if (name === "核对相近车证据") return `已核对相近车的数量、相似程度和价格分布；${audit}。`;
  if (name === "核对车辆差异") return `已逐项核对具体款型、上牌、里程、城市、过户、颜色和车况；${audit}。`;
  if (name === "校验收售价格梯度") return `已校验建议挂牌价、预计实际售卖价、最高收车价和预计实际收车价的大小关系；${audit}。`;
  if (name === "生成最终结果") {
    return `已合成定价模型结果、相近车证据、七要素修正和完整价格梯度，生成可审计定价报告；${audit}。`;
  }
  return Object.keys(result).length ? `业务步骤已完成，结果已进入任务卡；${audit}。` : `${audit}。`;
}

function compactList(value: unknown, limit = 2, maxLength = 56) {
  if (!Array.isArray(value)) return "";
  return value.slice(0, limit).map((item) => shortText(item, maxLength)).filter(Boolean).join("；");
}

function shortText(value: unknown, maxLength = 80) {
  const text = String(value || "").replace(/\s+/g, " ").trim();
  return text.length > maxLength ? `${text.slice(0, maxLength)}...` : text;
}

function formatCompactNumber(value: unknown) {
  const number = Number(value);
  return Number.isFinite(number) ? number.toFixed(1).replace(/\.0$/, "") : safeLabel(value);
}

function formatToolWan(value: unknown) {
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) return "-";
  const wan = number > 1000 ? number / 10000 : number;
  return `${wan.toFixed(2).replace(/\.00$/, "")}万`;
}

function safeLabel(value: unknown, fallback = "-") {
  const text = String(value || "").trim();
  return text || fallback;
}

function decisionLabel(value: unknown) {
  const key = String(value || "");
  const labels: Record<string, string> = {
    ready_for_pricing_workflow: "开始单车定价",
    blocked_before_pricing_workflow: "信息不足，等待补齐",
    non_pricing_route: "转到对应业务能力"
  };
  return labels[key] || safeLabel(value);
}

const SLOT_LABELS: Record<string, string> = {
  brand: "品牌",
  series: "车系/车型",
  model: "车型",
  trim: "款型配置",
  model_year: "车型年款",
  first_license_date: "上牌时间",
  first_license_year: "上牌时间",
  first_license_month: "上牌月份",
  city: "城市",
  mileage_wan_km: "公里数",
  mileage_km: "公里数",
  transfer_count: "过户次数",
  color: "颜色",
  vehicle_confirm: "标准车型",
  condition: "车况",
  condition_group: "车况",
  inspection_grade: "车况",
  standard_vehicle: "标准车型"
};

function slotLabel(field: string) {
  return SLOT_LABELS[field] || field;
}

function summarizeVehicleSlots(slots: Record<string, unknown>) {
  const rawVehicle =
    slots.vehicle_title ||
    slots.standard_vehicle ||
    slots.raw_vehicle_text ||
    [slots.brand, slots.series, slots.trim || slots.model || slots.canonical_trim_key].filter(Boolean).join(" ");
  const attrs = [
    slots.model_year ? `${String(slots.model_year).replace(/款$/, "")}款` : "",
    formatFirstLicense(slots),
    slots.mileage_wan_km ? `${slots.mileage_wan_km}万公里` : slots.mileage_km ? `${(Number(slots.mileage_km) / 10000).toFixed(1)}万公里` : "",
    slots.city,
    slots.transfer_count !== undefined && slots.transfer_count !== null && slots.transfer_count !== ""
      ? `${slots.transfer_count}次过户`
      : "",
    slots.color
  ]
    .filter(Boolean)
    .map(String)
    .join("、");
  return [rawVehicle, attrs].filter(Boolean).map(String).join(" · ");
}

function formatFirstLicense(slots: Record<string, unknown>) {
  const raw = String(slots.first_license_date || slots.reg_date || "").trim().replace("/", "-");
  const match = raw.match(/^((?:19|20)\d{2})(?:-(\d{1,2}))?/);
  if (match) {
    const month = match[2] || slots.first_license_month;
    return month ? `${match[1]}-${String(month).padStart(2, "0")}上牌` : `${match[1]}上牌`;
  }
  if (slots.first_license_year) {
    const month = slots.first_license_month ? `-${String(slots.first_license_month).padStart(2, "0")}` : "";
    return `${slots.first_license_year}${month}上牌`;
  }
  return "";
}

function toNumber(value: unknown): number | undefined {
  if (value === undefined || value === null || value === "") return undefined;
  if (typeof value === "number") return Number.isFinite(value) ? value : undefined;
  const text = String(value).trim();
  if (!text) return undefined;
  const match = text.match(/-?\d+(?:\.\d+)?/);
  if (!match) return undefined;
  const num = Number(match[0]);
  if (!Number.isFinite(num) || num <= 0) return undefined;
  return text.includes("万") && num < 1000 ? num * 10000 : num;
}

function extractPointPrice(price?: PricingResult): number | undefined {
  if (!price) return undefined;
  const candidates = [
    price.final_price,
    price.price?.point,
    price.c2bPrice,
    price.c2b_point,
    price.point_price,
    price.reference_price,
    price.primary_anchor_price,
    price.baseline_price
  ];
  for (const candidate of candidates) {
    const value = toNumber(candidate);
    if (value) return value;
  }
  return undefined;
}

function extractPriceRange(price: PricingResult | undefined, point?: number): { lower?: number; upper?: number; source: string } {
  if (!price) return { source: "missing" };
  const tupleRange = Array.isArray(price.c2bRange) ? price.c2bRange : undefined;
  const objectRange =
    (price.price_interval as Record<string, unknown> | undefined) ||
    (price.interval as Record<string, unknown> | undefined) ||
    (price.range as Record<string, unknown> | undefined);
  const lower =
    toNumber(price.price?.lower) ||
    toNumber(tupleRange?.[0]) ||
    toNumber(objectRange?.lower) ||
    toNumber(objectRange?.min) ||
    toNumber(price.lower) ||
    toNumber(price.c2b_lower);
  const upper =
    toNumber(price.price?.upper) ||
    toNumber(tupleRange?.[1]) ||
    toNumber(objectRange?.upper) ||
    toNumber(objectRange?.max) ||
    toNumber(price.upper) ||
    toNumber(price.c2b_upper);
  if (lower && upper) return { lower, upper, source: "engine" };
  return { source: "missing" };
}

function extractB2cPrice(
  price: PricingResult | undefined,
  _point?: number,
  _c2bLower?: number,
  _c2bUpper?: number
): { point?: number; lower?: number; upper?: number } {
  if (!price) return {};
  const b2cRange = Array.isArray(price.b2cRange) ? price.b2cRange : undefined;
  const b2cPoint = toNumber(price.b2cPrice) || toNumber(price.b2c_point);
  const lower = toNumber(b2cRange?.[0]) || toNumber(price.b2c_lower);
  const upper = toNumber(b2cRange?.[1]) || toNumber(price.b2c_upper);
  return { point: b2cPoint, lower, upper };
}

function extractPriceLadder(price: PricingResult | undefined): {
  listingPoint?: number;
  listingLower?: number;
  listingUpper?: number;
  maxC2b?: number;
} {
  if (!price) return {};
  const ladder = price.price_ladder || {};
  const listingRange = Array.isArray(price.recommended_listing_range_yuan)
    ? price.recommended_listing_range_yuan
    : Array.isArray(ladder.recommended_listing_range_yuan)
      ? ladder.recommended_listing_range_yuan
      : undefined;
  return {
    listingPoint:
      toNumber(price.recommended_listing_price_yuan) ||
      toNumber(ladder.recommended_listing_yuan),
    listingLower: toNumber(listingRange?.[0]),
    listingUpper: toNumber(listingRange?.[1]),
    maxC2b:
      toNumber(price.max_c2b_price_yuan) ||
      toNumber(ladder.max_c2b_yuan)
  };
}

function extractComparableItems(price?: PricingResult): Record<string, unknown>[] {
  if (!price) return [];
  const evidence = price.evidence_card as Record<string, unknown> | undefined;
  const groups = [
    price.selected_comparables,
    price.ref_cars,
    price.comparables,
    price.top_candidates,
    evidence?.selected_comparables,
    evidence?.top_comparables,
    evidence?.candidates
  ];
  for (const group of groups) {
    if (Array.isArray(group) && group.length) {
      const rows = group.filter((item) => item && typeof item === "object") as Record<string, unknown>[];
      const seen = new Set<string>();
      return rows.filter((item) => {
        const semanticParts = [item.vehicle, item.title, item.city, item.model_year, item.mileage_wan_km, item.transfer_count]
          .filter((value) => value !== undefined && value !== null && value !== "")
          .map(String);
        const key = semanticParts.length >= 3
          ? semanticParts.join("|")
          : String(item.lifecycle_key || item.candidate_id || JSON.stringify(item));
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      });
    }
  }
  return [];
}
