import { ChevronDown, SendHorizontal, SlidersHorizontal, X } from "lucide-react";
import { FormEvent, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { useAgentTurn } from "../../hooks/useAgentTurn";
import { useAgentStore } from "../../store/agentStore";
import { fetchMarketCities } from "../../api/agentClient";
import type { BusinessModule, VehicleSearchItem } from "../../types/agent";
import { VehicleSearchBox } from "../media-pricing/VehicleSearchBox";

export const cityOptions = [
  "全国",
  "北京",
  "重庆",
  "合肥",
  "武汉",
  "上海",
  "广州",
  "深圳",
  "成都",
  "杭州",
  "苏州",
  "南京",
  "天津",
  "郑州",
  "西安",
  "长沙",
  "佛山",
  "东莞"
];

const priorityCities = ["全国", "北京", "重庆", "合肥", "武汉"];

function orderCityOptions(cities: string[]) {
  const priority = new Map(priorityCities.map((city, index) => [city, index]));
  return [...cities].sort((left, right) => {
    const leftPriority = priority.get(left);
    const rightPriority = priority.get(right);
    if (leftPriority !== undefined || rightPriority !== undefined) {
      return (leftPriority ?? priorityCities.length) - (rightPriority ?? priorityCities.length);
    }
    return left.localeCompare(right, "zh-CN");
  });
}

export const energyTypeOptions = [
  "全部",
  "新能源",
  "燃油车"
];

export const bodyTypeOptions = [
  "全部",
  "轿车",
  "SUV",
  "MPV"
];

const placeholders: Record<BusinessModule, string> = {
  selection: "输入车系或问题，如：Model Y 能不能收 / 20万以内值得收的车",
  market: "问全国行情、今日日报、降价榜或具体车系动态",
  pricing: "输入车辆信息，如：2021款宝马3系 5万公里 上海"
};

const allowedVehicleColors = ["白", "黑", "灰", "银", "红", "蓝", "棕", "金", "绿", "黄", "橙", "紫"];

export function AgentComposer() {
  const activeModule = useAgentStore((state) => state.activeModule);
  const selectedCity = useAgentStore((state) => state.selectedCity);
  const selectedEnergyType = useAgentStore((state) => state.selectedEnergyType);
  const selectedBodyType = useAgentStore((state) => state.selectedBodyType);
  const currentSlots = useAgentStore((state) => state.clientState.current_slots || {});
  const currentVehicleMatch = useAgentStore((state) => state.clientState.current_vehicle_match || {});
  const setCity = useAgentStore((state) => state.setCity);
  const setEnergyType = useAgentStore((state) => state.setEnergyType);
  const setBodyType = useAgentStore((state) => state.setBodyType);
  const { sendTurn, isPending } = useAgentTurn();
  const [message, setMessage] = useState("");
  const [availableCityOptions, setAvailableCityOptions] = useState(cityOptions);
  const [editorOpen, setEditorOpen] = useState(false);
  const [vehicleForm, setVehicleForm] = useState(emptyVehicleForm);
  const [formError, setFormError] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const sheetRef = useRef<HTMLFormElement>(null);

  // A draft belongs to the module where it was typed. Keeping it while the
  // user switches modules made a pricing trim such as “美好” appear in the
  // market composer and, worse, allowed it to be submitted as a market query.
  useEffect(() => {
    setMessage("");
  }, [activeModule]);

  const leadText = useMemo(() => {
    if (activeModule === "selection") {
      return [selectedCity, selectedEnergyType !== "全部" ? selectedEnergyType : "", selectedBodyType !== "全部" ? selectedBodyType : ""]
        .filter(Boolean)
        .join(" ") + "，";
    }
    if (activeModule === "market") return "全国，";
    return "";
  }, [activeModule, selectedCity, selectedEnergyType, selectedBodyType]);

  useEffect(() => {
    let cancelled = false;
    fetchMarketCities()
      .then((cities) => {
        if (cancelled) return;
        const normalized = orderCityOptions(Array.from(
          new Set(["全国", ...cities.map((city) => String(city || "").trim()).filter((city) => city && city !== "全国")])
        ));
        if (normalized.length > 1) setAvailableCityOptions(normalized);
      })
      .catch(() => {
        if (!cancelled) setAvailableCityOptions(cityOptions);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!energyTypeOptions.includes(selectedEnergyType)) {
      setEnergyType("全部");
    }
    if (!bodyTypeOptions.includes(selectedBodyType)) {
      setBodyType("全部");
    }
  }, [selectedEnergyType, selectedBodyType, setEnergyType, setBodyType]);

  function submit(event: FormEvent) {
    event.preventDefault();
    const text = `${leadText}${message}`.trim();
    if (!text) return;
    sendTurn(text, {
      module: activeModule,
      payload: {
        selected_city: activeModule === "market" ? "全国" : selectedCity,
        selected_energy_type: selectedEnergyType,
        selected_body_type: selectedBodyType,
        selected_vehicle_category: selectedBodyType
      }
    });
    setMessage("");
  }

  useEffect(() => {
    function focusComposer() {
      inputRef.current?.focus();
    }
    function openPricingForm(event: Event) {
      const detail = (event as CustomEvent<Record<string, unknown>>).detail || {};
      const values = {
        ...currentSlots,
        vehicle_match: currentVehicleMatch,
        ...detail
      };
      setVehicleForm(toVehicleForm(values));
      setFormError("");
      setEditorOpen(true);
    }
    window.addEventListener("agent:focus-composer", focusComposer);
    window.addEventListener("agent:open-pricing-form", openPricingForm);
    return () => {
      window.removeEventListener("agent:focus-composer", focusComposer);
      window.removeEventListener("agent:open-pricing-form", openPricingForm);
    };
  }, [currentSlots, currentVehicleMatch]);

  useEffect(() => {
    if (!editorOpen) return;
    sheetRef.current?.focus();
    function closeOnEscape(event: KeyboardEvent) {
      if (event.key === "Escape") setEditorOpen(false);
    }
    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [editorOpen]);

  function submitVehicleUpdate(event: FormEvent) {
    event.preventDefault();
    const cleanVehicleText = cleanVehicleIdentityText(vehicleForm.vehicle);
    const selectedVehicleMatch = buildSelectedVehicleMatch(vehicleForm.selectedModel);
    const standardVehicle = selectedVehicleMatch?.model_name || selectedVehicleMatch?.title || cleanVehicleText;
    const missing = [
      !cleanVehicleText && "标准车型",
      !vehicleForm.licenseDate && "上牌时间",
      vehicleForm.mileage === "" && "里程",
      !vehicleForm.city.trim() && "城市",
      vehicleForm.transfer === "" && "过户次数",
      !vehicleForm.color.trim() && "颜色"
    ].filter(Boolean);
    if (missing.length) {
      setFormError(`请补齐：${missing.join("、")}`);
      return;
    }
    if (vehicleForm.licenseDate > currentMonthValue()) {
      setFormError("上牌时间不能晚于当前月份");
      return;
    }
    const normalizedCity = vehicleForm.city.trim().replace(/市$/, "");
    const validCities = new Set(availableCityOptions.map((city) => city.replace(/市$/, "")));
    if (!validCities.has(normalizedCity) || normalizedCity === "全国") {
      setFormError("请输入有效的国内城市，例如北京、重庆、合肥或武汉");
      return;
    }
    const normalizedColor = vehicleForm.color.trim().replace(/色$/, "");
    if (!allowedVehicleColors.some((color) => normalizedColor.includes(color))) {
      setFormError("请输入常见车辆颜色，例如白色、黑色、灰色、银色或蓝色");
      return;
    }
    const license = parseLicenseDate(vehicleForm.licenseDate);
    const fields = {
      raw_vehicle_text: cleanVehicleText,
      standard_vehicle: standardVehicle,
      trim: selectedVehicleMatch?.model_name || cleanVehicleText,
      brand: selectedVehicleMatch?.brand || undefined,
      series: selectedVehicleMatch?.series || undefined,
      model_year: selectedVehicleMatch?.model_year || undefined,
      model_id: selectedVehicleMatch?.model_id || undefined,
      vehicle_confirmed: true,
      first_license_date: license.date,
      first_license_year: license.year,
      first_license_month: license.month,
      mileage_wan_km: vehicleForm.mileage,
      city: normalizedCity,
      transfer_count: vehicleForm.transfer,
      color: normalizedColor,
      condition: vehicleForm.condition,
      condition_grade: vehicleForm.condition,
      inspection_grade: vehicleForm.condition,
      condition_group: vehicleForm.condition
    };
    sendTurn("已更新车辆七要素并重新估价", {
      module: "pricing",
      eventType: "field_update",
      payload: { type: "vehicle_parameters_update", fields, vehicle_match: selectedVehicleMatch || undefined }
    });
    setEditorOpen(false);
  }

  return (
    <>
    <form className={`agent-composer smart-input-box composer-${activeModule}`} onSubmit={submit}>
      {activeModule === "selection" ? <div className={`composer-filter-toolbar composer-filter-zone filter-zone-${activeModule}`}>
        <InlineSelect label="城市选择" value={selectedCity} options={availableCityOptions} onChange={setCity} />
        <SelectionCategoryFilter
          energy={selectedEnergyType}
          body={selectedBodyType}
          onEnergyChange={setEnergyType}
          onBodyChange={setBodyType}
        />
      </div> : null}
      <div className="composer-input-zone">
        <input
          ref={inputRef}
          className="composer-input"
          value={message}
          onChange={(event) => setMessage(event.target.value)}
          placeholder={placeholders[activeModule]}
        />
      </div>
      <button type="submit" disabled={isPending} aria-label="发送任务">
        <SendHorizontal size={20} />
        发送
      </button>
    </form>
    {editorOpen ? createPortal((
      <div className="vehicle-editor-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && setEditorOpen(false)}>
        <form ref={sheetRef} tabIndex={-1} className="vehicle-parameter-dialog vehicle-parameter-sheet" role="dialog" aria-modal="true" aria-label="修改车辆参数" onSubmit={submitVehicleUpdate}>
          <header>
            <div><SlidersHorizontal size={20} /><strong>修改车辆参数</strong></div>
            <button type="button" onClick={() => setEditorOpen(false)} aria-label="关闭参数编辑器"><X size={20} /></button>
          </header>
          <div className="vehicle-editor-fields sheet-body">
            <p className="sheet-intro">补齐车辆信息后将按新参数重新估价；车况可选，未选择时按良好车况估算并明确标记“未实车检测”。</p>
            {formError ? <p className="vehicle-form-error" role="alert">{formError}</p> : null}
            <label className={`vehicle-field-wide ${!vehicleForm.vehicle.trim() ? "field-missing" : ""}`}>
              <span>标准车型 <b aria-hidden="true">*</b></span>
              <VehicleSearchBox
                value={vehicleForm.vehicle}
                onChange={(value) => setVehicleForm((current) => ({ ...current, vehicle: value, selectedModel: null }))}
                onSelect={(item) => setVehicleForm((current) => ({ ...current, vehicle: cleanVehicleIdentityText(item.title), selectedModel: item }))}
              />
            </label>
            <label className={!vehicleForm.licenseDate ? "field-missing" : ""}><span>上牌时间 <b aria-hidden="true">*</b></span><input aria-label="上牌时间" type="month" max={currentMonthValue()} value={vehicleForm.licenseDate} onChange={(event) => setVehicleForm((current) => ({ ...current, licenseDate: event.target.value }))} /></label>
            <label className={vehicleForm.mileage === "" ? "field-missing" : ""}><span>里程（万公里） <b aria-hidden="true">*</b></span><input aria-label="里程（万公里）" type="number" min="0" step="0.1" value={vehicleForm.mileage} onChange={(event) => setVehicleForm((current) => ({ ...current, mileage: event.target.value }))} /></label>
            <label className={!vehicleForm.city.trim() ? "field-missing" : ""}><span>城市 <b aria-hidden="true">*</b></span><input aria-label="城市" value={vehicleForm.city} onChange={(event) => setVehicleForm((current) => ({ ...current, city: event.target.value }))} /></label>
            <label className={vehicleForm.transfer === "" ? "field-missing" : ""}><span>过户次数 <b aria-hidden="true">*</b></span><input aria-label="过户次数" type="number" min="0" step="1" value={vehicleForm.transfer} onChange={(event) => setVehicleForm((current) => ({ ...current, transfer: event.target.value }))} /></label>
            <label className={!vehicleForm.color.trim() ? "field-missing" : ""}><span>颜色 <b aria-hidden="true">*</b></span><input aria-label="颜色" value={vehicleForm.color} onChange={(event) => setVehicleForm((current) => ({ ...current, color: event.target.value }))} /></label>
            <fieldset className="vehicle-field-wide condition-grade-field">
              <legend>车况评级 <small>（可选，默认良好）</small></legend>
              <div className="condition-grade-options" role="radiogroup" aria-label="车况评级">
                {conditionGradeOptions.map((option) => (
                  <button
                    key={option.value}
                    type="button"
                    role="radio"
                    aria-checked={vehicleForm.condition === option.value}
                    className={vehicleForm.condition === option.value ? "active" : ""}
                    onClick={() => setVehicleForm((current) => ({ ...current, condition: option.value }))}
                    title={option.description}
                  >
                    <strong>{option.value}级</strong>
                    <span>{option.label}</span>
                    <small>{option.description}</small>
                  </button>
                ))}
              </div>
            </fieldset>
          </div>
          <footer>
            <button type="button" onClick={() => setEditorOpen(false)}>取消</button>
            <button type="submit">按新参数重新估价</button>
          </footer>
        </form>
      </div>
    ), document.body) : null}
    </>
  );
}

interface VehicleFormState {
  vehicle: string;
  licenseDate: string;
  mileage: string;
  city: string;
  transfer: string;
  color: string;
  condition: string;
  selectedModel: VehicleSearchItem | null;
}

const emptyVehicleForm: VehicleFormState = {
  vehicle: "",
  licenseDate: "",
  mileage: "",
  city: "",
  transfer: "",
  color: "",
  condition: "",
  selectedModel: null
};

function toVehicleForm(values: Record<string, unknown>): VehicleFormState {
  const vehicleMatch = vehicleMatchToSearchItem(values.vehicle_match as Record<string, unknown> | undefined);
  const vehicle = vehicleMatch?.title
    || values.standard_vehicle
    || values.vehicle_title
    || values.raw_vehicle_text
    || composeVehicleClue(values);
  return {
    vehicle: cleanVehicleIdentityText(String(vehicle || "")),
    licenseDate: normalizeLicenseDate(values),
    mileage: String(values.mileage_wan_km ?? ""),
    city: String(values.city || ""),
    transfer: String(values.transfer_count ?? ""),
    color: String(values.color || ""),
    condition: normalizeConditionGrade(values.condition_grade || values.condition),
    selectedModel: vehicleMatch
  };
}

function composeVehicleClue(values: Record<string, unknown>) {
  const brand = String(values.brand || "").trim();
  let series = String(values.series || "").trim();
  if (brand && series.replace(/\s+/g, "").startsWith(brand.replace(/\s+/g, ""))) {
    series = series.slice(series.indexOf(brand) + brand.length).trim();
  }
  return [values.model_year ? `${values.model_year}款` : "", brand, series, values.trim]
    .filter(Boolean)
    .join(" ");
}

const conditionGradeOptions = [
  { value: "A", label: "优秀", description: "原版原漆或仅轻微使用痕迹" },
  { value: "B", label: "良好", description: "少量补漆，常规整备即可" },
  { value: "C", label: "一般", description: "多处修复，整备成本较高" },
  { value: "D", label: "较差", description: "事故或结构件修复风险" },
  { value: "E", label: "特殊", description: "重大事故、水泡或火烧风险" }
] as const;

function normalizeConditionGrade(value: unknown) {
  const grade = String(value || "").trim().toUpperCase();
  return ["A", "B", "C", "D", "E"].includes(grade) ? grade : "";
}

function vehicleMatchToSearchItem(match?: Record<string, unknown>): VehicleSearchItem | null {
  if (!match) return null;
  if (match.need_manual_confirm) return null;
  const title = cleanVehicleIdentityText(String(match.title || match.display_name || match.model_name || match.model || ""));
  const modelId = String(match.model_id || match.id || "").trim();
  const brand = String(match.brand || match.brand_name || "").trim();
  const series = String(match.series || match.series_name || "").trim();
  const modelYear = String(match.model_year || "").trim();
  if (!title && !modelId) return null;
  return {
    id: modelId,
    model_id: modelId,
    title,
    model_name: title,
    model: title,
    brand,
    series,
    model_year: modelYear
  } as VehicleSearchItem;
}

function cleanVehicleIdentityText(value: string) {
  let text = String(value || "").trim();
  const patterns = [
    /[，,、]?\s*(?:19|20)\d{2}\s*[-/.]\s*\d{1,2}(?:\s*[-/.]\s*\d{1,2})?\s*(?:上牌|登记|落户)?/g,
    /[，,、]?\s*(?:19|20)\d{2}\s*年\s*\d{1,2}\s*月?\s*(?:上牌|登记|落户)?/g,
    /[，,、]?\s*-?\s*(?:0?[1-9]|1[0-2])\s*月?\s*(?:上牌|登记|落户)/g,
    /[，,、]?\s*\d+(?:\.\d+)?\s*万\s*公里/g,
    /[，,、]?\s*\d+(?:\.\d+)?\s*公里/g,
    /[，,、]?\s*\d+\s*次\s*过户/g
  ];
  patterns.forEach((pattern) => {
    text = text.replace(pattern, "");
  });
  return text.replace(/\s+/g, " ").trim().replace(/[，,、;；]+$/g, "").trim();
}

function buildSelectedVehicleMatch(item: VehicleSearchItem | null) {
  if (!item) return null;
  const modelId = String(item.model_id || item.id || "").trim();
  const title = cleanVehicleIdentityText(String(item.title || item.model_name || item.model || ""));
  const modelName = cleanVehicleIdentityText(String(item.model_name || item.model || title));
  return {
    model_id: modelId,
    id: modelId,
    title,
    model_name: modelName,
    model: modelName,
    brand: item.brand || "",
    series: item.series || "",
    model_year: item.model_year || "",
    matched: Boolean(modelId || title),
    need_manual_confirm: false
  };
}

function normalizeLicenseDate(values: Record<string, unknown>) {
  const raw = String(values.first_license_date || values.reg_date || "").trim().replace("/", "-");
  const rawMatch = raw.match(/^((?:19|20)\d{2})(?:-(\d{1,2}))?/);
  if (rawMatch) {
    const month = Math.max(1, Math.min(12, Number(rawMatch[2] || values.first_license_month || 1)));
    return `${rawMatch[1]}-${String(month).padStart(2, "0")}`;
  }
  const year = String(values.first_license_year || "").trim();
  if (!/^((?:19|20)\d{2})$/.test(year)) return "";
  const month = Math.max(1, Math.min(12, Number(values.first_license_month || 1)));
  return `${year}-${String(month).padStart(2, "0")}`;
}

function parseLicenseDate(value: string) {
  const match = String(value || "").match(/^((?:19|20)\d{2})-(\d{1,2})$/);
  if (!match) return { date: "", year: "", month: "" };
  const year = match[1];
  const month = String(Math.max(1, Math.min(12, Number(match[2])))).padStart(2, "0");
  return { date: `${year}-${month}`, year, month };
}

function currentMonthValue() {
  const now = new Date();
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
}

function InlineSelect({
  label,
  value,
  options,
  onChange
}: {
  label: string;
  value: string;
  options: string[];
  onChange: (value: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (!open) return;
    function closeOutside(event: PointerEvent) {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false);
    }
    document.addEventListener("pointerdown", closeOutside);
    return () => document.removeEventListener("pointerdown", closeOutside);
  }, [open]);
  return (
    <span className="inline-select" ref={rootRef}>
      <button
        type="button"
        aria-label={label}
        aria-expanded={open}
        aria-haspopup="listbox"
        className="inline-select-trigger"
        onClick={() => setOpen((current) => !current)}
        onKeyDown={(event) => {
          if (event.key === "Escape") setOpen(false);
        }}
      >
        {value}
        <ChevronDown size={14} />
      </button>
      {open ? (
        <span className="inline-select-menu">
          {options.map((option) => (
            <button
              key={option}
              type="button"
              className={option === value ? "inline-select-option active" : "inline-select-option"}
              onClick={() => {
                onChange(option);
                setOpen(false);
              }}
            >
              {option}
            </button>
          ))}
        </span>
      ) : null}
    </span>
  );
}

function SelectionCategoryFilter({
  energy,
  body,
  onEnergyChange,
  onBodyChange
}: {
  energy: string;
  body: string;
  onEnergyChange: (value: string) => void;
  onBodyChange: (value: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLSpanElement>(null);
  const selected = [energy !== "全部" ? energy : "", body !== "全部" ? body : ""].filter(Boolean);
  const label = selected.length ? `车型范围：${selected.join(" · ")}` : "车型范围：不限";

  useEffect(() => {
    if (!open) return;
    function closeOutside(event: MouseEvent) {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", closeOutside);
    return () => document.removeEventListener("mousedown", closeOutside);
  }, [open]);

  return (
    <span className="selection-category-filter" ref={rootRef}>
      <button
        type="button"
        aria-label="车型范围筛选"
        aria-expanded={open}
        aria-haspopup="dialog"
        className="inline-select-trigger selection-category-trigger"
        onClick={() => setOpen((current) => !current)}
      >
        {label}
        <ChevronDown size={14} />
      </button>
      {open ? (
        <span className="selection-category-menu" role="dialog" aria-label="选择车型范围">
          <span className="selection-category-heading"><strong>1 选择能源</strong><small>可不选</small></span>
          <span className="selection-category-options">
            {energyTypeOptions.map((option) => (
              <button key={option} type="button" className={option === energy ? "active" : ""} onClick={() => onEnergyChange(option)}>
                {option === "全部" ? "不限能源" : option}
              </button>
            ))}
          </span>
          <span className="selection-category-heading"><strong>2 选择车身</strong><small>可不选，直接执行</small></span>
          <span className="selection-category-options">
            {bodyTypeOptions.map((option) => (
              <button key={option} type="button" className={option === body ? "active" : ""} onClick={() => onBodyChange(option)}>
                {option === "全部" ? "不限车身" : option}
              </button>
            ))}
          </span>
          <span className="selection-category-actions">
            <button type="button" onClick={() => { onEnergyChange("全部"); onBodyChange("全部"); }}>清空</button>
            <button type="button" className="primary" onClick={() => setOpen(false)}>完成</button>
          </span>
        </span>
      ) : null}
    </span>
  );
}
