import { MessageSquareText } from "lucide-react";
import { useState } from "react";
import { submitInternalFeedback } from "../../api/agentClient";
import type { AgentTaskResponse } from "../../types/agent";

interface FeedbackOption {
  label: string;
  tag: string;
  rating: -1 | 1;
}

const OPTIONS: Record<string, FeedbackOption[]> = {
  pricing: [
    { label: "收车价准确", tag: "收车价准确", rating: 1 },
    { label: "收车价不准", tag: "收车价不准", rating: -1 },
    { label: "售车价准确", tag: "售车价准确", rating: 1 },
    { label: "售车价不准", tag: "售车价不准", rating: -1 },
  ],
  selection: [
    { label: "推荐车准确", tag: "推荐车准确", rating: 1 },
    { label: "推荐车不准", tag: "推荐车不准", rating: -1 },
    { label: "避免车准确", tag: "避免车准确", rating: 1 },
    { label: "避免车不准", tag: "避免车不准", rating: -1 },
  ],
  market: [
    { label: "信息不全", tag: "信息不全", rating: -1 },
    { label: "信息不准", tag: "信息不准", rating: -1 },
    { label: "有用", tag: "有用", rating: 1 },
    { label: "没用", tag: "没用", rating: -1 },
    { label: "信息新鲜", tag: "信息新鲜", rating: 1 },
    { label: "信息过时", tag: "信息过时", rating: -1 },
  ],
};

const TITLES: Record<string, string> = {
  pricing: "这次收车价和售车价准吗？",
  selection: "这次推荐收和避免收准吗？",
  market: "这次行情信息质量怎么样？",
};

export function TaskFeedback({ task }: { task: AgentTaskResponse }) {
  const module = normalizeModule(task.module, task.task_type);
  const options = OPTIONS[module] || OPTIONS.market;
  const [selected, setSelected] = useState("");
  const [comment, setComment] = useState("");
  const [open, setOpen] = useState(false);
  const [status, setStatus] = useState("");
  const selectedOption = options.find((item) => item.tag === selected);
  const prompt = selectedOption?.rating === 1
    ? "这项结果符合预期的原因是什么？也可以补充你最认可的数据或结论。"
    : selectedOption
      ? `“${selectedOption.label}”具体哪里不符合预期？请写明正确结果或业务场景。`
      : "请先选择一个反馈类型，再补充具体说明。";

  async function submit(option: FeedbackOption, detail = comment) {
    setStatus("正在记录…");
    try {
      await submitInternalFeedback({
        turn_id: task.task_id,
        rating: option.rating,
        comment: detail,
        tags: [module, task.task_type, option.tag]
      });
      setStatus("已记录，问题、上下文和回答已一并保存");
    } catch (reason) {
      setStatus(reason instanceof Error ? reason.message : "反馈记录失败");
    }
  }

  return (
    <section className={`task-feedback task-feedback-${module}`} aria-label="本次结果反馈">
      <div>
        <strong>{TITLES[module] || "这个结果准确吗？"}</strong>
        <span>选择后可补充说明并提交，系统会同时保存本次问题、上下文和回答。</span>
      </div>
      <div className="task-feedback-actions task-feedback-business-actions">
        {options.map((option) => (
          <button
            key={option.tag}
            className={`${selected === option.tag ? "active" : ""} ${option.rating < 0 ? "negative-option" : ""}`}
            type="button"
            onClick={() => {
              setSelected(option.tag);
              setOpen(true);
              setComment("");
              setStatus(option.rating > 0
                ? `已选择“${option.label}”，可补充符合预期的原因`
                : `已选择“${option.label}”，请补充不符合预期的具体位置`);
            }}
          >
            {option.label}
          </button>
        ))}
        <button type="button" onClick={() => setOpen((value) => !value)}><MessageSquareText size={16} /> 补充说明</button>
      </div>
      {open ? (
        <div className="task-feedback-editor">
          <strong>{selectedOption?.rating === 1 ? "哪些内容符合预期？" : selectedOption ? "具体哪里不对？" : "请先选择反馈类型"}</strong>
          <textarea value={comment} onChange={(event) => setComment(event.target.value)} placeholder={prompt} rows={3} />
          <button
            type="button"
            onClick={() => {
              const option = options.find((item) => item.tag === selected);
              if (option) void submit(option, comment);
            }}
            disabled={!selected}
          >提交反馈</button>
        </div>
      ) : null}
      {status ? <small className="task-feedback-status">{status}</small> : null}
    </section>
  );
}

function normalizeModule(value: string, taskType = "") {
  if (/selection|car_selection/i.test(taskType)) return "selection";
  if (value === "media_pricing") return "pricing";
  if (value === "market_state") return "market";
  return value;
}
