import { BarChart3, CarFront, ClipboardList } from "lucide-react";
import type { CSSProperties } from "react";
import type { BusinessModule } from "../../types/agent";
import progressCar from "../../assets/dcar_progress_car_premium.png?inline";

const modules: Array<{
  id: BusinessModule;
  title: string;
  description: string;
  icon: typeof ClipboardList;
}> = [
  {
    id: "market",
    title: "行情",
    description: "行业日报、城市行情和车系行情检索",
    icon: BarChart3
  },
  {
    id: "selection",
    title: "选品",
    description: "城市机会车系、风险车系和经营动作",
    icon: ClipboardList
  },
  {
    id: "pricing",
    title: "定价",
    description: "模型定价、七要素修正和收售价格边界",
    icon: CarFront
  }
];

interface ModuleSwitcherProps {
  activeModule: BusinessModule;
  onChange: (module: BusinessModule) => void;
  variant?: "hero" | "compact" | "landing";
}

export function ModuleSwitcher({ activeModule, onChange, variant = "hero" }: ModuleSwitcherProps) {
  if (variant === "landing") {
    const activeIndex = Math.max(0, modules.findIndex((module) => module.id === activeModule));
    const positions = [16.67, 50, 83.33];
    const routeStyle = {
      "--route-position": `${positions[activeIndex]}%`,
      "--route-progress": `${positions[activeIndex]}%`
    } as CSSProperties;
    return (
      <section className="landing-route" aria-label="业务链路" style={routeStyle}>
        <div className="landing-route-grid">
          {modules.map((module, index) => (
            <button
              key={module.id}
              className={`landing-route-stage ${module.id === activeModule ? "landing-route-stage-current" : ""}`}
              onClick={() => onChange(module.id)}
              type="button"
              aria-pressed={module.id === activeModule}
            >
              <strong>{String(index + 1).padStart(2, "0")}</strong>
              <span>
                <b>{module.title}</b>
                <small>{module.id === "market" ? "洞察真实市场行情" : module.id === "selection" ? "发现高潜在供车机会" : "智能生成最优报价"}</small>
              </span>
            </button>
          ))}
        </div>
        <div className="landing-route-track" aria-hidden="true">
          <i />
          {modules.map((module, index) => (
            <span
              key={module.id}
              className={`landing-route-dot dot-${index + 1} ${module.id === activeModule ? "active" : ""}`}
              style={{ left: `${positions[index]}%` }}
            />
          ))}
          <img src={progressCar} alt="" />
        </div>
      </section>
    );
  }
  return (
    <section className={`module-tabs ${variant === "compact" ? "module-tabs-compact" : ""}`} aria-label="业务模块">
      {modules.map((module) => {
        const Icon = module.icon;
        const active = module.id === activeModule;
        return (
          <button
            key={module.id}
            className={`module-tab ${active ? "module-tab-active" : ""}`}
            onClick={() => onChange(module.id)}
            type="button"
          >
            <Icon size={20} />
            <span>
              <strong>{module.title}</strong>
              <small>{module.description}</small>
            </span>
          </button>
        );
      })}
    </section>
  );
}
