import { AgentComposer } from "./components/chat/AgentComposer";
import { ChatPanel } from "./components/chat/ChatPanel";
import { ModuleSwitcher } from "./components/layout/ModuleSwitcher";
import { QuickCommandBar } from "./components/layout/QuickCommandBar";
import { InternalAuthGate, useInternalAuth } from "./components/layout/InternalAuthGate";
import { FeedbackAdminPage } from "./components/feedback/FeedbackAdminPage";
import { SelectionStrategyLab } from "./components/selection-lab/SelectionStrategyLab";
import { logoutInternalUser } from "./api/agentClient";
import { useAgentStore } from "./store/agentStore";

const OFFICIAL_DCAR_LOGO_URL =
  "https://lf3-motor.dcarstatic.com/obj/motor-fe-static/motor/pc/_next/./static/images/logo-fcf421caf44b23091eee..svg";

export function App() {
  let content = <AgentApp />;
  if (window.location.pathname.includes("/agent/selection-lab")) content = <SelectionStrategyLab />;
  if (window.location.pathname.includes("/agent/feedback")) content = <FeedbackAdminPage />;
  return <InternalAuthGate>{content}</InternalAuthGate>;
}

function AgentApp() {
  const auth = useInternalAuth();
  const activeModule = useAgentStore((state) => state.activeModule);
  const setModule = useAgentStore((state) => state.setModule);
  const messages = useAgentStore((state) => state.messages);

  const isHome = messages.length === 0;

  async function logout() {
    try {
      await logoutInternalUser();
    } finally {
      // A hard navigation remounts the auth gate and also avoids retaining
      // any in-memory conversation after an internal tester signs out.
      window.location.assign(`/agent?logged_out=${Date.now()}`);
    }
  }

  return (
    <main className={isHome ? "agent-page agent-page-home" : "agent-page"}>
      <nav className="internal-top-actions" aria-label="内部测试工具">
        {auth.can_view_feedback ? <a href="/agent/feedback">反馈记录</a> : null}
        {auth.label ? <span className="internal-account-label">{auth.label}</span> : null}
        <button type="button" onClick={() => void logout()}>退出</button>
      </nav>
      {isHome ? (
        <div className="home-brand-lockup" aria-label="懂车帝 AI懂车价">
          <span className="home-official-dcar-logo" aria-hidden="true">
            <img src={OFFICIAL_DCAR_LOGO_URL} alt="" referrerPolicy="no-referrer" />
          </span>
          <span className="home-brand-divider" aria-hidden="true" />
          <span className="home-ai-wordmark" aria-hidden="true">AI懂车价</span>
        </div>
      ) : null}
      <section className="agent-hero">
        <p className="hero-kicker">DONGCHEDI USED CAR AGENT</p>
        <h1 className="hero-title">
          <span className="title-main">AI懂车价</span>
          <span className="title-sep">｜</span>
          <span className="title-sub">二手车行情与估价</span>{" "}
          <span className="title-agent">Agent</span>
        </h1>
        <p className="hero-subtitle">面向二手车业务的任务型 Agent：把行情日报、城市选品和单车估价串成可追踪的业务链路。</p>
      </section>

      <ModuleSwitcher activeModule={activeModule} onChange={setModule} variant={isHome ? "landing" : "hero"} />

      {!isHome ? (
        <section className="task-workspace">
          <ChatPanel messages={messages} />
        </section>
      ) : null}

      <section className={isHome ? "smart-console smart-console-home" : "smart-console"}>
        {!isHome ? (
          <div className="console-module-switcher">
            <ModuleSwitcher activeModule={activeModule} onChange={setModule} variant="compact" />
          </div>
        ) : null}
        <QuickCommandBar activeModule={activeModule} />
        <AgentComposer />
      </section>
    </main>
  );
}
